    // out from under a reticle you have just put on a zombie (measured: at 0.26s, two
    // shots in three missed). Driven from the cursor's SCREEN position, not the world
    // point under it: the screen position doesn't move when the camera pans, so the pan
    // target holds still and converges. World-derived pan feeds back on itself and creeps.
    const PAN_MAX = 3.0, PAN_DEAD = 0.18, PAN_TAU = 0.1;
