    let lookSens = 1;
    try { const s = +localStorage.getItem('tt_look_sens'); if (s >= 0.25 && s <= 3) lookSens = s; } catch (_) {}

    // Base arm / elbow pose (weapon hold)
    const ARM_L_BASE = { x: -0.85, y: 0.15, z: 0.55 };
    const ARM_R_BASE = { x: -1.05, y: -0.05, z: -0.25 };
    const ELBOW_L_BASE = { x: -0.35, y: 0, z: 0 };
    const ELBOW_R_BASE = { x: -0.2, y: 0, z: 0 };
    // GB-124 (Jerry): unarmed, his arms hang at his sides (see updateMarinePose). Shoulder pitch (a touch forward),
    // twist (thumbs turned forward), the swing out from the body, and the slight bend at the elbow; mirrored per side.
    const UNARMED_ARMS = { x: -0.02, y: -0.25, z: 0.05, elbow: -0.22 };
    // GB-125 (Jerry): the tactical crouch (see "Crouch" and "Crouch legs" in updateMarinePose). Body drop and chest lean;
    // the leg chain (hip pivot height, thigh, shin, ankle to sole, sole toe / heel reach, from studio/marine-body.js);
    // the crouched stance (front foot flat, rear foot back on its ball, knees a touch wide); the crouch-walk step
    // (half step length, share of the cycle the foot is planted, swing lift); and the unarmed arms over the thighs.
    const CROUCH = { drop: 0.2, lean: 0.36, hipY: 0.62, L1: 0.27, L2: 0.25, ankleH: 0.104, toe: 0.174, heel: 0.107,
      frontZ: 0.15, rearZ: -0.07, rearPitch: 0.45, splay: 0.09, step: 0.25, stance: 0.55, lift: 0.045, maxCad: 15,
      armFwd: 0.1, armBend: 0.3, armOut: 0.06 };

    function updateTacticalHud() {
      if (!tacticalLineEl) return;
      const g = gearOwned;
      tacticalLineEl.textContent =
        'NVG ' + (!g.nvg ? '—' : (nvgDown ? (isNight ? 'ON' : 'down') : 'off')) +
        ' · Laser ' + (!g.laser ? '—' : (lasersEnabled ? 'ON' : 'off')) +
        ' · Light ' + (!g.flashlight ? '—' : (flashlightOn ? 'ON' : 'off'));
    }

    // Tactical gear is bought, not issued. Toggling something you don't own just
    // points you at the kiosk.
    function needGear(key, label) {
      if (gearOwned[key]) return true;
      AudioSys.invalid();
      showBanner(label.toUpperCase() + ' NOT OWNED', 'Buy it at the kiosk (Gear tab)', 1.6, '#ffb347');
      return false;
    }
    let flashlightOn = false;
    // Built once, at load, and parented to the scene rather than to the weapon mount.
    // Creating it on first press cost a full shader rebuild the moment you hit L, and
    // hanging it off the weapon mount meant it vanished from the light set whenever the
    // mount hid (swimming, manning the mortar) — another rebuild, each way. Scene-level
    // and always present: only its transform and intensity change.
    const flashlight = new THREE.SpotLight(0xfff2d0, 0, 26, 0.42, 0.55, 1.1);
    flashlight.castShadow = false;
    scene.add(flashlight);
    scene.add(flashlight.target);
    const _flashDir = new THREE.Vector3();
    function updateFlashlight() {
      const on = flashlightOn && gearOwned.flashlight && gameStarted && !gameOver && !won;
      // Brighter when it's actually dark; barely-there in daylight so it doesn't
      // bleach the ground in front of you at noon.
      flashlight.intensity = on ? (isNight ? 42 : 6) : 0;
      if (!on) return;
      // Follow the muzzle by hand, since it is no longer a child of the gun.
      flashlight.position.copy(getMuzzleWorld());
      _flashDir.copy(getAimDir());
      flashlight.target.position.copy(flashlight.position).addScaledVector(_flashDir, 10);
      flashlight.target.updateMatrixWorld();
    }
    function toggleFlashlight() {
      if (!gameStarted || gameOver || won) return;
      if (!needGear('flashlight', 'Flashlight')) return;
      flashlightOn = !flashlightOn;
      AudioSys.nvgClick();
      updateFlashlight();
      updateTacticalHud();
    }

    function updateNvgVisual() {
      const activeGreen = nvgDown && isNight && gameStarted && !gameOver && !won;
      renderer.domElement.classList.toggle('nvg-phosphor', activeGreen);
      if (nvgOverlayEl) {
        if (activeGreen) nvgOverlayEl.classList.add('on');
        else nvgOverlayEl.classList.remove('on');
      }
      if (activeGreen && hurtFlash <= 0) {
        scene.background.setHex(0x111b22);
        scene.fog.color.setHex(0x1c2930);
        // Preserve moonlit shape and dark occlusion instead of flooding every face.
        ambientFill.intensity = Math.max(ambientFill.intensity, 0.22);
        hemi.intensity = Math.max(hemi.intensity, 0.62);
        moon.intensity = Math.max(moon.intensity, 0.82);
        scene.fog.near = Math.min(scene.fog.near, 55);
        scene.fog.far = Math.max(scene.fog.far, 170);
      }
    }

    // The engine and the goggles are running sounds: settled every frame from what
    // is in hand and whether the game is actually being played.
    function updateGearSounds() {
      const live = gameStarted && !gameOver && !won;
      const hold = paused || shopOpen;
      const sawWant = live && currentWeapon === 'chainsaw' && sawFuel > 0 && !playerSwimming && !mortarMounted && !mortarCarried;
      AudioSys.chainsawEngine(sawWant && !hold, hold || !live);
      AudioSys.nvgHum(live && nvgDown && !hold);
      if (hold || !live) { AudioSys.turretServos(null); AudioSys.stopFlames(); }
    }
    function toggleNvg() {
      if (!gameStarted || gameOver || won) return;
      if (!needGear('nvg', 'Night vision')) return;
      nvgDown = !nvgDown;
      AudioSys.nvgToggle(nvgDown);
      updateNvgVisual();
      updateTacticalHud();
    }

    function toggleLasers() {
      if (gameStarted && !needGear('laser', 'Laser sight')) return;
      lasersEnabled = !lasersEnabled;
      AudioSys.nvgClick();
      updateLasers();
      updateTacticalHud();
    }

    function getStanceEyeY() { return EYE_Y; }

    // --- Player animation state ---
    // Everything here is re-derived each frame from targets and eased, so a missed
    // frame or a mode switch can never leave a limb stuck mid-pose.
    const POSE = {
      lowerYaw: 0,        // eased yaw of the legs relative to the aim line
      lean: 0, leanSide: 0,
      landT: 0,           // landing-squash timer
      airT: 0,            // how long we've been airborne
      wasGroundedPose: true,
      idleT: 0,
      kneeL: 0, kneeR: 0,
      thighL: 0, thighR: 0,
      strideDir: 1,       // +1 forward, -1 backpedal (cycle runs in reverse)
      bodyDip: 0,
      lastVy: 0,
      crouch: 0           // 0=standing..1=fully crouched, eased both ways
