    }

    // GP-74: a cosmetic idle layer; all action poses retain priority.
    const marineIdle = createMarineIdle({ THREE, marine, scene,
      solveArm: (side, target) => solveArmIK(marine.userData['arm' + side + 'G'], marine.userData['elbow' + side + 'G'],
        side === 'R' ? _HAND_R : _HAND_L, target, side === 'R' ? _POLE_R : _POLE_L, 1),
      smoke: (...args) => spawnSmokePuff(...args), ground: (x, z) => sampleHeight(x, z),
      ignite: (x, z) => spawnGroundFire(x, z, false, 0, true)
    });
    let marineIdleInput = false;
    for (const event of ['keydown', 'pointerdown', 'pointermove', 'wheel']) {
