    }
    function updateMarineIdle(dt) {
      // GB-102 (P-109, D-60): no cigarette in the rain. A lit one hisses out (a puff of steam) and he stays merely
      // bored instead of reaching for the pack (SMOKE_AFTER is 25 s in studio/marine-idle.js).
      if (weather.intensity > 0.1) {
        const st = marineIdle.state;
        if (st.phase === 'pack' || st.phase === 'smoking') {
          if (st.lit) spawnSmokePuff(player.position.x, player.position.y + 1.65, player.position.z, { tone: 'pale', size: 0.14, grow: 0.5, vy: 0.5, life: 0.9, peak: 0.45 });
