      const legL = ud.legLG, legR = ud.legRG;
      const kneeL = ud.kneeLG, kneeR = ud.kneeRG;
      const armL = ud.armLG, armR = ud.armRG;
      const elbowL = ud.elbowLG, elbowR = ud.elbowRG;
      const nvg = ud.nvgPivot;
      const hip = ud.hip;
      const lower = ud.lowerBody, torso = ud.torsoG, head = ud.headG;
      dt = Math.min(dt, 0.05);
