        if (ud.ankleRG) ud.ankleRG.rotation.x = kR * 0.5;
        if (torso) torso.rotation.set(0.55 * buckle - 0.2 * fall, 0.1 * fall, 0.15 * fall);
        if (head) head.rotation.set(0.5 * buckle - 0.6 * fall, 0.2 * fall, 0.2 * fall);
        if (armL) { armL.rotation.x = ARM_L_BASE.x + 0.9 * buckle - 1.0 * fall; armL.rotation.z = ARM_L_BASE.z + 0.4 * fall; }
        if (armR) { armR.rotation.x = ARM_R_BASE.x + 0.9 * buckle - 0.8 * fall; armR.rotation.z = ARM_R_BASE.z - 0.3 * fall; }
