        rollPivot.rotation.set(0, 0, 0, 'XYZ');
        rollPivot.position.y = ROLL_PIVOT_Y;
      }

      // Holster whatever gun is equipped while swimming — tryFire is already gated on
      // playerSwimming so it can't actually be fired, but it was still visibly dangling
      // from your hand the whole time you were paddling.
      const smokingIdle = marineIdle.state.phase === 'pack' || marineIdle.state.phase === 'smoking';
      weaponMount.visible = !swimming && !mortarMounted && !mortarCarried && !smokingIdle && !unarmed;
