      hitReaction.time = Math.max(0, hitReaction.time - dt);
      const hit = hitReaction.strength * Math.pow(hitReaction.time / hitReaction.duration, 2);

      // Aim brace: slight extra elbow bend when zoomed
      // Sniper / M4: light LH forend brace in idle/hold (does not affect pistol/uzi)
      const aimBrace = zoomHeld ? 0.12 : 0;
      const sniperForend = (
        (currentWeapon === 'sniper' && !reloading) ? 0.14 :
