      let bodyY = 0;
      let torsoLean = 0, torsoSide = 0, torsoTwist = 0, torsoRoll = 0;
      let headPitch = 0, headYaw = 0, headRoll = 0;
      let hipRoll = 0;
      let lowerYawTarget = 0;
      // Turn rate of the aim line this frame: standing still, the feet lag a fast
      // turn and then shuffle round to catch up.
      const dAim = _wrapAngle(aimYaw - (POSE.prevAim == null ? aimYaw : POSE.prevAim));
      POSE.prevAim = aimYaw;
      POSE.turnLag = _ease(POSE.turnLag || 0, Math.max(-0.7, Math.min(0.7, -dAim / Math.max(dt, 1e-3) * 0.09)), dt, 6);

      if (swimming) {
