        // distinct from the on-foot walk cycle so wading out past your depth actually
        // reads as swimming rather than walking in place underwater.
        const cadence = 9;
        walkPhase += dt * cadence;
        const kick = Math.sin(walkPhase) * 0.4;
        POSE.thighL = kick; POSE.thighR = -kick;
        if (legL) legL.rotation.z = 0;
        if (legR) legR.rotation.z = 0;
        POSE.kneeL = _ease(POSE.kneeL, 0.35 + Math.max(0, kick) * 0.8, dt, 14);
        POSE.kneeR = _ease(POSE.kneeR, 0.35 + Math.max(0, -kick) * 0.8, dt, 14);
        const stroke = Math.sin(walkPhase * 0.5);
        if (armL) {
          armL.rotation.x = ARM_L_BASE.x - 1.0 + stroke * 0.35;
          armL.rotation.y = ARM_L_BASE.y;
          armL.rotation.z = ARM_L_BASE.z;
        }
        if (armR) {
          armR.rotation.x = ARM_R_BASE.x - 1.0 - stroke * 0.35;
