        if (elbowL) elbowL.rotation.set(ELBOW_L_BASE.x - 0.45, ELBOW_L_BASE.y, ELBOW_L_BASE.z);
        if (elbowR) elbowR.rotation.set(ELBOW_R_BASE.x - 0.45, ELBOW_R_BASE.y, ELBOW_R_BASE.z);
