        // Direction of travel relative to the aim line. The legs face along it
        // (clamped — knees don't rotate 180°), the cycle reverses for a backpedal,
        // and the torso counter-twists a little so the shoulders stay on target.
        const spd = Math.hypot(velX, velZ);
        let rel = 0;
        if (spd > 0.3) rel = _wrapAngle(Math.atan2(velX, velZ) - aimYaw);
        let backpedal = false;
        if (Math.abs(rel) > Math.PI * 0.55) { rel = _wrapAngle(rel + Math.PI); backpedal = true; }
