        // the foot covers 2 x step in the stance share of the cycle), capped at maxCad so it never turns into a scurry.
        // Above maxCad * 2 * step / (2 PI * stance) = 2.2 m/s the feet would slide by the rest; PHYS.crouch is 2.2 (GB-126), so a plain crouch-walk does not slide.
        const crouchCad = Math.max(4, Math.min(CROUCH.maxCad, spd * Math.PI * CROUCH.stance / CROUCH.step));
        const cadence = running ? 14 : 9.5 + (crouchCad - 9.5) * POSE.crouch;
        const stride = running ? 0.7 : 0.5 - 0.2 * POSE.crouch;
        walkPhase += dt * cadence * (backpedal ? -1 : 1);
        const p = walkPhase;
        const sL = Math.sin(p), sR = Math.sin(p + Math.PI);
        // Thigh swings; the body sinks a touch at every heel strike (twice per cycle).
