        const kBase = running ? 0.28 : 0.1;
        const kSwing = running ? 1.35 : 0.85;
        POSE.kneeL = _ease(POSE.kneeL, kBase + Math.max(0, -Math.cos(p)) * kSwing, dt, 30);
        POSE.kneeR = _ease(POSE.kneeR, kBase + Math.max(0, Math.cos(p)) * kSwing, dt, 30);
