      add(new THREE.CylinderGeometry(0.026, 0.026, 0.2, 12), medPenBodyMat, 0);
      add(new THREE.CylinderGeometry(0.028, 0.028, 0.075, 12), medPenFluidMat, 0.02);
      for (const y of [-0.02, 0.06]) add(new THREE.CylinderGeometry(0.03, 0.03, 0.012, 12), medPenDarkMat, y);
      add(new THREE.CylinderGeometry(0.03, 0.03, 0.035, 12), medPenCapMat, 0.115);       // cap / plunger end
