      // to stay fixed (see the light-stability notes), so strip it back out.
      const doomed = [];
      m.traverse((o) => { if (o.isLight) doomed.push(o); });
      for (const d of doomed) d.parent.remove(d);
      // clone() does not rebind userData references to descendants. Without this,
