      chainsaw: { name: 'Chainsaw', maxAmmo: Infinity, reload: 0, interval: 0.12, damage: 14, spin: false, auto: true, melee: true, reach: 3.1, arc: 0.20 }   // GB-52: was 17 and arc -0.05
    };
