    const WEAPON_PRICE = { pistol: 0, uzi: 75, shotgun: 110, m4: 180, ak: 245, revolver: 145, sniper: 320, aa12: 650, launcher: 480, minigun: 850, flamer: 340, chainsaw: 190 };
    const WEAPON_BLURB = {
      pistol: 'Sidearm. Reliable, slow.', uzi: 'Spray-and-pray SMG. Short range, fast.', shotgun: 'Seven-pellet pump. Devastating up close.',
