    const SHOTGUN_MOUNT_BASE = { x: 0.0, y: 0.016, z: 0.016, rx: 1.05, ry: 0.055, rz: 0.045 };
    // Grenade launcher — chunky palm seat, forward pitch like rifle holds
    const LAUNCHER_MOUNT_BASE = { x: 0.0, y: 0.018, z: 0.018, rx: 1.05, ry: 0.06, rz: 0.05 };
    // Minigun — hand-seated (not chest-float); slightly lower for bulk
    const MINIGUN_MOUNT_BASE = { x: 0.0, y: 0.012, z: 0.01, rx: 1.05, ry: 0.05, rz: 0.04 };
    // AK / AA-12 — same rifle-ish palm seat as the M4
    const AK_MOUNT_BASE = { x: 0.0, y: 0.017, z: 0.017, rx: 1.05, ry: 0.06, rz: 0.05 };
    const AA12_MOUNT_BASE = { x: 0.0, y: 0.016, z: 0.016, rx: 1.05, ry: 0.055, rz: 0.045 };
    // Chainsaw — light hand seat only (melee already polished)
    const CHAINSAW_MOUNT_BASE = { x: 0.0, y: 0.015, z: 0.012, rx: 1.05, ry: 0.055, rz: 0.045 };
    function getWeaponMountBase(w = currentWeapon) {
      if (w === 'pistol') return PISTOL_MOUNT_BASE;
      if (w === 'sniper') return SNIPER_MOUNT_BASE;
      if (w === 'uzi') return UZI_MOUNT_BASE;
      if (w === 'm4') return M4_MOUNT_BASE;
      if (w === 'ak') return AK_MOUNT_BASE;
      if (w === 'aa12') return AA12_MOUNT_BASE;
      if (w === 'revolver') return REVOLVER_MOUNT_BASE;
      if (w === 'shotgun') return SHOTGUN_MOUNT_BASE;
      if (w === 'launcher') return LAUNCHER_MOUNT_BASE;
      if (w === 'minigun') return MINIGUN_MOUNT_BASE;
      if (w === 'chainsaw') return CHAINSAW_MOUNT_BASE;
      return WEAPON_MOUNT_BASE;
    }
    const GUN_BASE = {
      minigun: { pos: minigun.position.clone(), rot: minigun.rotation.clone() },
      m4: { pos: m4.position.clone(), rot: m4.rotation.clone() },
      ak: { pos: ak.position.clone(), rot: ak.rotation.clone() },
      aa12: { pos: aa12.position.clone(), rot: aa12.rotation.clone() },
      pistol: { pos: pistol.position.clone(), rot: pistol.rotation.clone() },
      uzi: { pos: uzi.position.clone(), rot: uzi.rotation.clone() },
      shotgun: { pos: shotgun.position.clone(), rot: shotgun.rotation.clone() },
      revolver: { pos: revolver.position.clone(), rot: revolver.rotation.clone() },
      sniper: { pos: sniper.position.clone(), rot: sniper.rotation.clone() },
      launcher: { pos: launcher.position.clone(), rot: launcher.rotation.clone() },
      flamer: { pos: flamer.position.clone(), rot: flamer.rotation.clone() },
      chainsaw: { pos: chainsaw.position.clone(), rot: chainsaw.rotation.clone() }
    };
    let reloadArmOff = { x: 0, y: 0, z: 0 };
    let reloadArmOffL = { x: 0, y: 0, z: 0 };
    let reloadElbowOffR = { x: 0, y: 0, z: 0 };
    let reloadElbowOffL = { x: 0, y: 0, z: 0 };
    let reloadMountOff = { rx: 0, ry: 0, rz: 0, y: 0 };
    // Viewmodel kick (applied on top of mount base + reloadMountOff)
    let recoilKick = { x: 0, y: 0, z: 0, rx: 0, ry: 0, rz: 0 };
    let pistolSlideKick = 0;
    // Marine torso reaction to fire — separate from gun-mount kick so the body
    // absorbs heavier weapons more visibly (shoulders tip back / settle).
    let bodyRecoil = { lean: 0, side: 0, dip: 0, twist: 0, brace: 0, gripR: 0, gripL: 0 };

    function applyWeaponMountPose() {
      const mb = getWeaponMountBase();
      weaponMount.position.set(
        mb.x + recoilKick.x,
        mb.y + reloadMountOff.y + recoilKick.y,
        mb.z + recoilKick.z
      );
      weaponMount.rotation.set(
        mb.rx + reloadMountOff.rx + recoilKick.rx,
        mb.ry + reloadMountOff.ry + recoilKick.ry,
        mb.rz + reloadMountOff.rz + recoilKick.rz
      );
    }

    function punchBodyRecoil(scale) {
      // Each shot travels through the firing wrist, shoulder, torso and stance.
      // In akimbo the opposite hand stays steady instead of both guns jolting.
      const s = Math.max(0.15, scale);
      const left = akimboOn() && lastFiredGun === offhandMeshes[currentWeapon];
      const side = left ? -1 : 1;
      bodyRecoil.lean += -0.07 * s - Math.random() * 0.025 * s;   // tip back
      bodyRecoil.side += (-side * 0.024 + (Math.random() - 0.5) * 0.025) * s;
      bodyRecoil.dip += -0.016 * s - Math.random() * 0.008 * s;   // settle into stance
      bodyRecoil.twist += side * 0.036 * s;
      bodyRecoil.brace += 0.085 * s;
      if (left) bodyRecoil.gripL -= 0.075 * s;
      else bodyRecoil.gripR -= 0.075 * s;
      bodyRecoil.lean = Math.max(-0.32, Math.min(0.04, bodyRecoil.lean));
      bodyRecoil.side = Math.max(-0.14, Math.min(0.14, bodyRecoil.side));
      bodyRecoil.dip = Math.max(-0.07, Math.min(0.02, bodyRecoil.dip));
      bodyRecoil.twist = Math.max(-0.16, Math.min(0.16, bodyRecoil.twist));
      bodyRecoil.brace = Math.min(0.32, bodyRecoil.brace);
      bodyRecoil.gripR = Math.max(-0.18, bodyRecoil.gripR);
      bodyRecoil.gripL = Math.max(-0.18, bodyRecoil.gripL);
    }

    function applyPistolFireSlide() {
      if (currentWeapon !== 'pistol' || reloading) return;
      for (const gun of [pistol, offhandMeshes.pistol]) {
        if (!gun?.userData.slide) continue;
        const bp = gun.userData.baseSlidePos;
        gun.userData.slide.position.set(bp.x, bp.y, bp.z - (gun.userData.slideKick || 0));
      }
    }

    function decayRecoil(dt) {
      // Sniper lingers; M4 medium; Uzi chatters back fast; pistol/others snap
      const rate =
        currentWeapon === 'sniper' ? 9 :
        currentWeapon === 'launcher' ? 8.5 :
        currentWeapon === 'shotgun' ? 8 :
        currentWeapon === 'revolver' ? 10.5 :
        currentWeapon === 'm4' ? 12 :
        currentWeapon === 'minigun' ? 18 :
        currentWeapon === 'uzi' ? 16 :
        14;
      const k = Math.min(1, dt * rate);
      recoilKick.x *= (1 - k);
      recoilKick.y *= (1 - k);
      recoilKick.z *= (1 - k);
      recoilKick.rx *= (1 - k);
      recoilKick.ry *= (1 - k);
      recoilKick.rz *= (1 - k);
      pistolSlideKick *= (1 - Math.min(1, dt * 13));
      for (const gun of [pistol, offhandMeshes.pistol]) gun.userData.slideKick = (gun.userData.slideKick || 0) * Math.exp(-22 * dt);
      // Body settles a touch slower than the gun mount so the kick reads as absorbed.
      const bk = Math.min(1, dt * 7.5);
      bodyRecoil.lean *= (1 - bk);
      bodyRecoil.side *= (1 - bk);
      bodyRecoil.dip *= (1 - bk);
      bodyRecoil.twist *= (1 - bk);
      bodyRecoil.brace *= (1 - bk);
      bodyRecoil.gripR *= (1 - Math.min(1, dt * 13));
      bodyRecoil.gripL *= (1 - Math.min(1, dt * 13));
      if (Math.abs(bodyRecoil.lean) < 1e-4) bodyRecoil.lean = 0;
      if (Math.abs(bodyRecoil.side) < 1e-4) bodyRecoil.side = 0;
      if (Math.abs(bodyRecoil.dip) < 1e-4) bodyRecoil.dip = 0;
      if (Math.abs(bodyRecoil.twist) < 1e-4) bodyRecoil.twist = 0;
      if (Math.abs(bodyRecoil.brace) < 1e-4) bodyRecoil.brace = 0;
      if (Math.abs(bodyRecoil.gripR) < 1e-4) bodyRecoil.gripR = 0;
      if (Math.abs(bodyRecoil.gripL) < 1e-4) bodyRecoil.gripL = 0;
      if (pistolSlideKick < 1e-4) pistolSlideKick = 0;
    }

    function kickPistolRecoil() {
      // Muzzle tips up (negative rx), tiny roll, push back in hand-local -z/-y
      recoilKick.rx += -0.17 - Math.random() * 0.04; // ~-0.17..-0.21
      recoilKick.rz += (Math.random() - 0.5) * 0.055;
      recoilKick.ry += (Math.random() - 0.5) * 0.02;
      recoilKick.z += -0.015 - Math.random() * 0.006;
      recoilKick.y += -0.008 - Math.random() * 0.004;
      recoilKick.x += (Math.random() - 0.5) * 0.004;
      // Clamp so stacked kicks can't flip the mount
      recoilKick.rx = Math.max(-0.36, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.08, Math.min(0.08, recoilKick.ry));
      recoilKick.rz = Math.max(-0.12, Math.min(0.12, recoilKick.rz));
      recoilKick.x = Math.max(-0.03, Math.min(0.03, recoilKick.x));
      recoilKick.y = Math.max(-0.035, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.04, Math.min(0.02, recoilKick.z));
      // Do not rack the slide on fire: barrel/compensator stay on the frame, so a
      // slide-only kick leaves the muzzle floating ahead of the gun body. Mount
      // recoil above still kicks; reload anim still racks the slide over the barrel.
      pistolSlideKick = 0;
      for (const g of [pistol, offhandMeshes.pistol]) {
        if (g) g.userData.slideKick = 0;
        if (g?.userData.slide && g.userData.baseSlidePos) g.userData.slide.position.copy(g.userData.baseSlidePos);
      }
      punchBodyRecoil(0.55);
      applyWeaponMountPose();
    }

    function kickSniperRecoil() {
      // Heavier than pistol: bigger muzzle climb, stronger push-back, higher clamp
      recoilKick.rx += -0.30 - Math.random() * 0.08; // ~-0.30..-0.38
      recoilKick.rz += (Math.random() - 0.5) * 0.07;
      recoilKick.ry += (Math.random() - 0.5) * 0.025;
      recoilKick.z += -0.028 - Math.random() * 0.01;
      recoilKick.y += -0.012 - Math.random() * 0.006;
      recoilKick.x += (Math.random() - 0.5) * 0.006;
      recoilKick.rx = Math.max(-0.55, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.10, Math.min(0.10, recoilKick.ry));
      recoilKick.rz = Math.max(-0.14, Math.min(0.14, recoilKick.rz));
      recoilKick.x = Math.max(-0.04, Math.min(0.04, recoilKick.x));
      recoilKick.y = Math.max(-0.045, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.06, Math.min(0.02, recoilKick.z));
      punchBodyRecoil(1.35);
      applyWeaponMountPose();
    }

    function kickUziRecoil() {
      // SMG chatter: smaller per-shot than pistol, stacks a bit; very slight cyclic climb
      recoilKick.rx += -0.095 - Math.random() * 0.03; // ~-0.095..-0.125
      recoilKick.rx += -0.012; // light cyclic climb while auto
      recoilKick.rz += (Math.random() - 0.5) * 0.045;
      recoilKick.ry += (Math.random() - 0.5) * 0.018;
      recoilKick.z += -0.010 - Math.random() * 0.004;
      recoilKick.y += -0.005 - Math.random() * 0.003;
      recoilKick.x += (Math.random() - 0.5) * 0.0035;
      recoilKick.rx = Math.max(-0.42, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.08, Math.min(0.08, recoilKick.ry));
      recoilKick.rz = Math.max(-0.11, Math.min(0.11, recoilKick.rz));
      recoilKick.x = Math.max(-0.028, Math.min(0.028, recoilKick.x));
      recoilKick.y = Math.max(-0.032, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.036, Math.min(0.02, recoilKick.z));
      punchBodyRecoil(0.4);
      applyWeaponMountPose();
    }

    function kickM4Recoil() {
      // Medium kick — between pistol and sniper
      recoilKick.rx += -0.22 - Math.random() * 0.05; // ~-0.22..-0.27
      recoilKick.rz += (Math.random() - 0.5) * 0.06;
      recoilKick.ry += (Math.random() - 0.5) * 0.022;
      recoilKick.z += -0.020 - Math.random() * 0.008;
      recoilKick.y += -0.010 - Math.random() * 0.005;
      recoilKick.x += (Math.random() - 0.5) * 0.005;
      recoilKick.rx = Math.max(-0.46, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.09, Math.min(0.09, recoilKick.ry));
      recoilKick.rz = Math.max(-0.13, Math.min(0.13, recoilKick.rz));
      recoilKick.x = Math.max(-0.035, Math.min(0.035, recoilKick.x));
      recoilKick.y = Math.max(-0.040, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.050, Math.min(0.02, recoilKick.z));
      punchBodyRecoil(0.85);
      applyWeaponMountPose();
    }

    function kickRevolverRecoil() {
      // Heavy single-action kick — stout muzzle climb, medium-slow decay (~10.5/s)
      recoilKick.rx += -0.32 - Math.random() * 0.08; // ~-0.32..-0.40
      recoilKick.rz += (Math.random() - 0.5) * 0.075;
      recoilKick.ry += (Math.random() - 0.5) * 0.03;
      recoilKick.z += -0.030 - Math.random() * 0.012;
      recoilKick.y += -0.014 - Math.random() * 0.006;
      recoilKick.x += (Math.random() - 0.5) * 0.007;
      recoilKick.rx = Math.max(-0.58, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.11, Math.min(0.11, recoilKick.ry));
      recoilKick.rz = Math.max(-0.15, Math.min(0.15, recoilKick.rz));
      recoilKick.x = Math.max(-0.04, Math.min(0.04, recoilKick.x));
      recoilKick.y = Math.max(-0.048, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.065, Math.min(0.02, recoilKick.z));
      punchBodyRecoil(1.15);
      applyWeaponMountPose();
    }

    function kickShotgunRecoil() {
      // Heavier punch — stronger climb + push-back, slower settle (~8/s)
      recoilKick.rx += -0.40 - Math.random() * 0.10; // ~-0.40..-0.50
      recoilKick.rz += (Math.random() - 0.5) * 0.10;
      recoilKick.ry += (Math.random() - 0.5) * 0.04;
      recoilKick.z += -0.040 - Math.random() * 0.014;
      recoilKick.y += -0.020 - Math.random() * 0.008;
      recoilKick.x += (Math.random() - 0.5) * 0.01;
      recoilKick.rx = Math.max(-0.68, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.14, Math.min(0.14, recoilKick.ry));
      recoilKick.rz = Math.max(-0.18, Math.min(0.18, recoilKick.rz));
      recoilKick.x = Math.max(-0.05, Math.min(0.05, recoilKick.x));
      recoilKick.y = Math.max(-0.06, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.08, Math.min(0.02, recoilKick.z));
      punchBodyRecoil(1.45);
      applyWeaponMountPose();
    }

    function kickLauncherRecoil() {
      // Between shotgun and sniper — strong climb + pushback, slow decay (~8.5/s)
      recoilKick.rx += -0.36 - Math.random() * 0.09; // ~-0.36..-0.45
      recoilKick.rz += (Math.random() - 0.5) * 0.09;
      recoilKick.ry += (Math.random() - 0.5) * 0.035;
      recoilKick.z += -0.036 - Math.random() * 0.012;
      recoilKick.y += -0.018 - Math.random() * 0.007;
      recoilKick.x += (Math.random() - 0.5) * 0.009;
      recoilKick.rx = Math.max(-0.62, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.13, Math.min(0.13, recoilKick.ry));
      recoilKick.rz = Math.max(-0.17, Math.min(0.17, recoilKick.rz));
      recoilKick.x = Math.max(-0.048, Math.min(0.048, recoilKick.x));
      recoilKick.y = Math.max(-0.055, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.075, Math.min(0.02, recoilKick.z));
      punchBodyRecoil(1.4);
      applyWeaponMountPose();
    }

    function kickMinigunRecoil() {
      // Sustained chatter — light per-shot, stacks a bit; fast decay (~18/s)
      recoilKick.rx += -0.055 - Math.random() * 0.025;
      recoilKick.rx += -0.008; // light cyclic climb while spinning
      recoilKick.rz += (Math.random() - 0.5) * 0.05;
      recoilKick.ry += (Math.random() - 0.5) * 0.02;
      recoilKick.z += -0.008 - Math.random() * 0.004;
      recoilKick.y += -0.004 - Math.random() * 0.003;
      recoilKick.x += (Math.random() - 0.5) * 0.004;
      recoilKick.rx = Math.max(-0.38, Math.min(0.05, recoilKick.rx));
      recoilKick.ry = Math.max(-0.09, Math.min(0.09, recoilKick.ry));
      recoilKick.rz = Math.max(-0.12, Math.min(0.12, recoilKick.rz));
      recoilKick.x = Math.max(-0.03, Math.min(0.03, recoilKick.x));
      recoilKick.y = Math.max(-0.028, Math.min(0.02, recoilKick.y));
      recoilKick.z = Math.max(-0.032, Math.min(0.02, recoilKick.z));
      punchBodyRecoil(0.35);
      applyWeaponMountPose();
    }

    function startShotgunPump() {
      shotgunPumping = true;
      shotgunPumpT = 0;
      shotgunPumpEjected = false;
      shotgunPumpSfxBack = false;
      shotgunPumpSfxFwd = false;
    }

    function updateShotgunPump(dt) {
      if (!shotgunPumping) return;
      const gun = weaponMeshes.shotgun;
      shotgunPumpT += dt / Math.max(0.05, SHOTGUN_PUMP_DUR);
      const t = shotgunPumpT;
      // Back → hold open → slam forward
      let pumpAmt = 0;
      if (t < 0.30) pumpAmt = _seg(t, 0.02, 0.26);
      else if (t < 0.50) pumpAmt = 1;
      else pumpAmt = 1 - _seg(t, 0.50, 0.94);
      if (!shotgunPumpSfxBack && t >= 0.04) {
        shotgunPumpSfxBack = true;
        if (AudioSys.shotgunPump) AudioSys.shotgunPump();
      }
      if (!shotgunPumpSfxFwd && t >= 0.50) {
        shotgunPumpSfxFwd = true;
        if (AudioSys.shotgunPump) AudioSys.shotgunPump();
      }

      const travel = 0.24; // forend slide distance
      const base = GUN_BASE.shotgun;

      if (gun && !reloading) {
        // Only the forend racks. Receiver + barrel + mag tube stay locked to gun pose
        // (LH tracks the pump via holdWeapon). Sliding the whole gun forward used to
        // make barrel/tube look like they detached from the rest of the weapon.
        if (base) {
          gun.position.copy(base.pos);
          gun.rotation.copy(base.rot);
        }
        if (gun.userData.pump && gun.userData.basePumpPos) {
          const bp = gun.userData.basePumpPos;
          gun.userData.pump.position.set(bp.x, bp.y, bp.z - travel * pumpAmt);
        }
        // RH locked on grip — zero tumble offsets
        reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
        reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;
        // LH follows the racking forend (holdWeapon uses pump position)
        reloadArmOffL.x = -0.06 * pumpAmt;
        reloadArmOffL.y = 0.03 * pumpAmt;
        reloadArmOffL.z = 0.04 * pumpAmt;
        reloadElbowOffL.x = -0.18 * pumpAmt;
        reloadElbowOffL.y = 0;
        reloadElbowOffL.z = 0.05 * pumpAmt;
        // Mount: tiny left roll only — align skipped while pumping
        reloadMountOff.rx = -0.03 * pumpAmt;
        reloadMountOff.ry = 0;
        reloadMountOff.rz = 0.10 * pumpAmt;
        reloadMountOff.y = 0.004 * pumpAmt;
      }

      if (!shotgunPumpEjected && t >= 0.26) {
        shotgunPumpEjected = true;
        spawnShotgunShell();
      }
      if (t >= 1) {
        shotgunPumping = false;
        shotgunPumpT = 1;
        if (gun && !reloading) {
          if (base) {
            gun.position.copy(base.pos);
            gun.rotation.copy(base.rot);
          }
          if (gun.userData.pump && gun.userData.basePumpPos) {
            gun.userData.pump.position.copy(gun.userData.basePumpPos);
          }
          reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
          reloadArmOffL.x = reloadArmOffL.y = reloadArmOffL.z = 0;
          reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;
          reloadElbowOffL.x = reloadElbowOffL.y = reloadElbowOffL.z = 0;
          reloadMountOff.rx = reloadMountOff.ry = reloadMountOff.rz = reloadMountOff.y = 0;
        }
      }
    }

    function _clamp01(t) { return Math.max(0, Math.min(1, t)); }
    function _smooth(t) { t = _clamp01(t); return t * t * (3 - 2 * t); }
    function _lerp(a, b, t) { return a + (b - a) * t; }
    function _seg(progress, a, b) {
      if (b <= a) return progress >= b ? 1 : 0;
      return _smooth((progress - a) / (b - a));
    }
    function _pulse(progress, a, b, c) {
      // 0→1 over a..b, 1→0 over b..c
      if (progress <= a) return 0;
      if (progress >= c) return 0;
      if (progress < b) return _seg(progress, a, b);
      return 1 - _seg(progress, b, c);
    }

    function resetReloadAnim() {
      reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
      reloadArmOffL.x = reloadArmOffL.y = reloadArmOffL.z = 0;
      reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;
      reloadElbowOffL.x = reloadElbowOffL.y = reloadElbowOffL.z = 0;
      reloadMountOff.rx = reloadMountOff.ry = reloadMountOff.rz = reloadMountOff.y = 0;
      applyWeaponMountPose();
      const elbowL = marine.userData.elbowLG;
      const elbowR = marine.userData.elbowRG;
      // GB-125: not while the unarmed arms are relaxed (POSE.relax, GB-124): updateMarinePose has already set the
      // elbows this frame, and this (run on every quiet frame) was flattening their bend back to the gun hold's.
      if (!(POSE.relax > 0.001)) {
        if (elbowL) elbowL.rotation.set(ELBOW_L_BASE.x, ELBOW_L_BASE.y, ELBOW_L_BASE.z);
        if (elbowR) elbowR.rotation.set(ELBOW_R_BASE.x, ELBOW_R_BASE.y, ELBOW_R_BASE.z);
      }
      for (const name of WEAPON_ORDER) {
        const gun = weaponMeshes[name];
        const base = GUN_BASE[name];
        if (!gun || !base) continue;
        gun.position.copy(base.pos);
        gun.rotation.copy(base.rot);
        if (gun.userData.barrelAssembly) {
          gun.userData.barrelAssembly.rotation.x = gun.userData.baseBarrelRotX || 0;
          gun.userData.barrelAssembly.rotation.y = 0;
        }
        if (gun.userData.ammoBox && gun.userData.baseAmmoPos) {
          gun.userData.ammoBox.position.copy(gun.userData.baseAmmoPos);
          gun.userData.ammoBox.rotation.copy(gun.userData.baseAmmoRot);
          gun.userData.ammoBox.visible = true;
        }
        if (gun.userData.mag && gun.userData.baseMagPos) {
          gun.userData.mag.position.copy(gun.userData.baseMagPos);
          if (gun.userData.baseMagRot) gun.userData.mag.rotation.copy(gun.userData.baseMagRot);
          gun.userData.mag.visible = true;
        }
        if (gun.userData.slide && gun.userData.baseSlidePos) {
          gun.userData.slide.position.copy(gun.userData.baseSlidePos);
        }
        if (gun.userData.bolt && gun.userData.baseBoltPos) {
          gun.userData.bolt.position.copy(gun.userData.baseBoltPos);
          if (gun.userData.baseBoltRot) gun.userData.bolt.rotation.copy(gun.userData.baseBoltRot);
        }
        if (gun.userData.pump && gun.userData.basePumpPos) {
          gun.userData.pump.position.copy(gun.userData.basePumpPos);
        }
        if (gun.userData.reloadShell) {
          gun.userData.reloadShell.visible = false;
          if (gun.userData.baseReloadShellPos) {
            gun.userData.reloadShell.position.copy(gun.userData.baseReloadShellPos);
          }
        }
        if (gun.userData.cylinder && gun.userData.baseCylinderRot) {
          gun.userData.cylinder.rotation.copy(gun.userData.baseCylinderRot);
          if (gun.userData.baseCylinderPos) gun.userData.cylinder.position.copy(gun.userData.baseCylinderPos);
        }
        if (gun.userData.hammer && gun.userData.baseHammerRot) {
          gun.userData.hammer.rotation.copy(gun.userData.baseHammerRot);
          if (gun.userData.baseHammerPos) gun.userData.hammer.position.copy(gun.userData.baseHammerPos);
        }
        if (gun.userData.drum && gun.userData.baseDrumRot) {
          gun.userData.drum.rotation.copy(gun.userData.baseDrumRot);
          if (gun.userData.baseDrumPos) gun.userData.drum.position.copy(gun.userData.baseDrumPos);
        }
      }
      applyPistolFireSlide();
      syncDualWeaponParts();
    }

    // One-off gestures with the off hand, played over whatever the gun hand is doing:
    // lobbing a bag of skulls into the HQ, jabbing a MedPen into a thigh.
    let gestureT = 0, gestureDur = 0, gestureKind = '';
    function playGesture(kind, dur) { gestureKind = kind; gestureDur = dur; gestureT = dur; }
    function playThrowPose() { playGesture('throw', 0.6); }
    function updateGesture(dt) {
      if (!(gestureT > 0)) return;
      gestureT = Math.max(0, gestureT - dt);
      const u = 1 - gestureT / gestureDur;
      if (gestureKind === 'throw') {
        // Wind up over the shoulder, then fling forward and let the arm fall.
        const wind = u < 0.4 ? Math.sin(u / 0.4 * Math.PI / 2) : 1 - (u - 0.4) / 0.6;
        const fling = u > 0.4 ? Math.sin((u - 0.4) / 0.6 * Math.PI) : 0;
        reloadArmOffL.x = -2.1 * wind - 0.5 * fling;
        reloadArmOffL.z = 0.35 * wind;
        reloadElbowOffL.x = -0.9 * wind + 0.4 * fling;
      } else if (gestureKind === 'jab') {
        // Down to the thigh, a sharp stab, hold, then back up.
        const reach = u < 0.3 ? Math.sin(u / 0.3 * Math.PI / 2) : (u > 0.75 ? 1 - (u - 0.75) / 0.25 : 1);
        const stab = u > 0.3 && u < 0.55 ? Math.sin((u - 0.3) / 0.25 * Math.PI) : 0;
        reloadArmOffL.x = (0.6 * reach + 0.35 * stab);
        reloadArmOffL.z = 0.5 * reach;
        reloadElbowOffL.x = -0.55 * reach + 0.35 * stab;
      }
    }
    function updateReloadAnim(dt) {
      const armR = marine.userData.armRG;
      const armL = marine.userData.armLG;
      const elbowR = marine.userData.elbowRG;
      const elbowL = marine.userData.elbowLG;
      decayRecoil(dt);

      function applyReloadPose() {
        // Hand-local base + reload tilt + recoil kick (gun follows arm via gripR parent)
        applyWeaponMountPose();
        if (armR) {
          armR.rotation.x += reloadArmOff.x;
          armR.rotation.y += reloadArmOff.y;
          armR.rotation.z += reloadArmOff.z;
        }
        if (armL) {
          armL.rotation.x += reloadArmOffL.x;
          armL.rotation.y += reloadArmOffL.y;
          armL.rotation.z += reloadArmOffL.z;
        }
        if (elbowR) {
          elbowR.rotation.x += reloadElbowOffR.x;
          elbowR.rotation.y += reloadElbowOffR.y;
          elbowR.rotation.z += reloadElbowOffR.z;
        }
        if (elbowL) {
          elbowL.rotation.x += reloadElbowOffL.x;
          elbowL.rotation.y += reloadElbowOffL.y;
          elbowL.rotation.z += reloadElbowOffL.z;
        }
      }

      if (!reloading) {
        if (!shotgunPumping) {
          const k = Math.min(1, dt * 12);
          reloadArmOff.x *= (1 - k); reloadArmOff.y *= (1 - k); reloadArmOff.z *= (1 - k);
          reloadArmOffL.x *= (1 - k); reloadArmOffL.y *= (1 - k); reloadArmOffL.z *= (1 - k);
          reloadElbowOffR.x *= (1 - k); reloadElbowOffR.y *= (1 - k); reloadElbowOffR.z *= (1 - k);
          reloadElbowOffL.x *= (1 - k); reloadElbowOffL.y *= (1 - k); reloadElbowOffL.z *= (1 - k);
          reloadMountOff.rx *= (1 - k); reloadMountOff.ry *= (1 - k);
          reloadMountOff.rz *= (1 - k); reloadMountOff.y *= (1 - k);
          if (swapT > 0) {
            swapT = Math.max(0, swapT - dt);
            const dip = Math.sin((1 - swapT / swapDur) * Math.PI);
            reloadArmOff.x = 0.5 * dip; reloadArmOff.z = -0.12 * dip;
            reloadArmOffL.x = 0.45 * dip; reloadArmOffL.z = 0.15 * dip;
            reloadElbowOffR.x = -0.35 * dip;
            reloadElbowOffL.x = -0.3 * dip;
            reloadMountOff.rx = 0.4 * dip; reloadMountOff.y = -0.03 * dip;
          }
          updateGesture(dt);
        }
        updateShotgunPump(dt);
        const quiet =
          !(gestureT > 0) &&
          !shotgunPumping &&
          Math.abs(reloadArmOff.x) < 1e-4 && Math.abs(reloadMountOff.rx) < 1e-4 &&
          Math.abs(reloadElbowOffR.x) < 1e-4 && Math.abs(reloadElbowOffL.x) < 1e-4;
        if (quiet) resetReloadAnim();
        else {
          applyReloadPose();
          applyPistolFireSlide();
        }
        return;
      }

      const st = WEAPON_STATS[currentWeapon];
      const dur = Math.max(0.05, reloadAnimDuration || st.reload);
      const progress = _clamp01(1 - reloadTimer / dur);
      playReloadCues(progress);
      const gun = getActiveGun();

      reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
      reloadArmOffL.x = reloadArmOffL.y = reloadArmOffL.z = 0;
      reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;
      reloadElbowOffL.x = reloadElbowOffL.y = reloadElbowOffL.z = 0;
      reloadMountOff.rx = reloadMountOff.ry = reloadMountOff.rz = reloadMountOff.y = 0;

      if (currentWeapon === 'minigun') {
        // RH locked (pistol playbook) — modest tip only; LH swaps ammo box. No gun spin / RH tumble.
        const tipUp = _seg(progress, 0.0, 0.16);
        const tipDown = _seg(progress, 0.78, 0.96);
        const tip = tipUp * (1 - tipDown);
        const boxOpen = _seg(progress, 0.12, 0.30);
        const boxShut = _seg(progress, 0.68, 0.84);
        const box = boxOpen * (1 - boxShut);
        const fetchDown = _pulse(progress, 0.18, 0.28, 0.38);
        const fetchUp = _seg(progress, 0.32, 0.48);
        const seat = _pulse(progress, 0.55, 0.68, 0.82);

        reloadMountOff.rx = -0.14 * tip;
        reloadMountOff.rz = 0.04 * tip;
        reloadMountOff.y = 0.006 * tip;
        reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
        reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;

        // LH: fetch / seat ammo box
        reloadArmOffL.x = -0.18 * fetchDown - 0.10 * fetchUp - 0.12 * seat - 0.06 * tip;
        reloadArmOffL.y = 0.10 * fetchDown + 0.05 * fetchUp;
        reloadArmOffL.z = 0.14 * fetchDown + 0.08 * fetchUp + 0.04 * tip;
        reloadElbowOffL.x = -0.75 * fetchDown - 0.48 * fetchUp - 0.90 * seat - 0.15 * tip;
        reloadElbowOffL.y = 0.10 * fetchDown;
        reloadElbowOffL.z = 0.08 * fetchUp - 0.10 * seat;

        const base = GUN_BASE.minigun;
        if (base) {
          gun.position.copy(base.pos);
          gun.rotation.copy(base.rot);
        }
        // Keep barrels level during reload (no tumble)
        if (gun.userData.barrelAssembly) {
          gun.userData.barrelAssembly.rotation.x = gun.userData.baseBarrelRotX || 0;
          gun.userData.barrelAssembly.rotation.y = 0;
        }
        if (gun.userData.ammoBox && gun.userData.baseAmmoPos) {
          const ab = gun.userData.ammoBox;
          ab.visible = true;
          ab.position.set(
            gun.userData.baseAmmoPos.x + 0.05 * box,
            gun.userData.baseAmmoPos.y - 0.08 * box,
            gun.userData.baseAmmoPos.z + 0.02 * box
          );
          ab.rotation.z = (gun.userData.baseAmmoRot?.z || 0.12) + 0.75 * box;
          ab.rotation.x = 0.4 * box;
        }
        barrelSpinVel = Math.max(0, barrelSpinVel - SPIN_DECEL * 1.4 * dt);
      } else if (currentWeapon === 'uzi') {
        // RH locked (pistol playbook) — tip-back only; LH fetch/seat; snappy SMG timing
        const present = _seg(progress, 0.0, 0.14);
        const recover = _seg(progress, 0.88, 1.0);
        const tilt = present * (1 - recover);

        const drop = _seg(progress, 0.08, 0.28);
        const holdGone = progress >= 0.28 && progress < 0.40;
        const insert = _seg(progress, 0.40, 0.62);
        const insertSettle = _seg(progress, 0.62, 0.70);

        const fetchDown = _pulse(progress, 0.24, 0.32, 0.40);
        const fetchUp = _seg(progress, 0.34, 0.44);
        const slap = _pulse(progress, 0.52, 0.60, 0.70);

        if (!reloadMagDropped && progress >= 0.12) {
          reloadMagDropped = true;
          spawnDroppedMag();
        }

        reloadMountOff.rx = -0.20 * tilt;
        reloadMountOff.rz = 0.05 * tilt;
        reloadMountOff.y = 0;
        reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
        reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;

        reloadArmOffL.x = -0.20 * fetchDown - 0.10 * fetchUp - 0.10 * slap;
        reloadArmOffL.y = 0.11 * fetchDown + 0.05 * fetchUp;
        reloadArmOffL.z = 0.16 * fetchDown + 0.08 * fetchUp;
        reloadElbowOffL.x = -0.82 * fetchDown - 0.52 * fetchUp - 0.95 * slap;
        reloadElbowOffL.y = 0.12 * fetchDown;
        reloadElbowOffL.z = 0.08 * fetchUp - 0.12 * slap;

        const base = GUN_BASE.uzi;
        if (base) {
          gun.position.copy(base.pos);
          gun.rotation.copy(base.rot);
        }

        if (gun.userData.mag && gun.userData.baseMagPos) {
          const mag = gun.userData.mag;
          const bp = gun.userData.baseMagPos;
          const dropY = 0.42;
          if (holdGone) {
            mag.visible = false;
            mag.position.set(bp.x, bp.y - dropY, bp.z + 0.05);
            mag.rotation.x = 0;
            mag.rotation.z = 0;
          } else if (progress < 0.28) {
            mag.visible = true;
            mag.position.set(
              bp.x + 0.03 * drop,
              bp.y - dropY * drop,
              bp.z + 0.05 * drop
            );
            mag.rotation.x = 0.55 * drop;
            mag.rotation.z = 0.28 * drop;
          } else {
            mag.visible = true;
            const over = 0.024;
            let yOff;
            if (progress < 0.62) yOff = -dropY * (1 - insert) + over * insert;
            else yOff = over * (1 - insertSettle);
            mag.position.set(bp.x, bp.y + yOff, bp.z);
            mag.rotation.x = 0.12 * (1 - Math.max(insert, insertSettle));
            mag.rotation.z = 0;
          }
        }
      } else if (currentWeapon === 'm4' || currentWeapon === 'ak' || currentWeapon === 'aa12') {
        // Every mag-fed long gun runs the same beats: tip back for the magwell, drop
        // the empty, left hand fetches and slams the fresh one home. Only how far the
        // magazine has to travel differs — an AK mag is deeper than an M4's and the
        // AA-12's drum deeper still, and a drum is slower to line up.
        const deep = currentWeapon === 'aa12' ? 0.60 : (currentWeapon === 'ak' ? 0.52 : 0.46);
        const present = _seg(progress, 0.0, 0.15);
        const recover = _seg(progress, 0.90, 1.0);
        const tilt = present * (1 - recover);

        const drop = _seg(progress, 0.08, 0.28);
        const holdGone = progress >= 0.28 && progress < 0.42;
        const insert = _seg(progress, 0.42, 0.64);
        const insertSettle = _seg(progress, 0.64, 0.74);

        const fetchDown = _pulse(progress, 0.24, 0.32, 0.40);
        const fetchUp = _seg(progress, 0.34, 0.44);
        const slap = _pulse(progress, 0.50, 0.60, 0.72);

        if (!reloadMagDropped && progress >= 0.12) {
          reloadMagDropped = true;
          spawnDroppedMag();
        }

        reloadMountOff.rx = -0.20 * tilt;
        reloadMountOff.rz = 0.04 * tilt;
        reloadMountOff.y = 0;
        reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
        reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;

        // Left hand: fetch → seat slam
        reloadArmOffL.x = -0.20 * fetchDown - 0.10 * fetchUp - 0.12 * slap;
        reloadArmOffL.y = 0.10 * fetchDown + 0.05 * fetchUp;
        reloadArmOffL.z = 0.16 * fetchDown + 0.08 * fetchUp;
        reloadElbowOffL.x = -0.80 * fetchDown - 0.50 * fetchUp - 1.05 * slap;
        reloadElbowOffL.y = 0.12 * fetchDown;
        reloadElbowOffL.z = 0.08 * fetchUp - 0.14 * slap;

        const base = GUN_BASE[currentWeapon];
        if (base) {
          gun.position.copy(base.pos);
          gun.rotation.copy(base.rot);
        }

        if (gun.userData.mag && gun.userData.baseMagPos) {
          const mag = gun.userData.mag;
          const bp = gun.userData.baseMagPos;
          const dropY = deep;
          if (holdGone) {
            mag.visible = false;
            mag.position.set(bp.x, bp.y - dropY, bp.z + 0.05);
            mag.rotation.x = 0;
            mag.rotation.z = 0;
          } else if (progress < 0.28) {
            mag.visible = true;
            mag.position.set(
              bp.x + 0.03 * drop,
              bp.y - dropY * drop,
              bp.z + 0.05 * drop
            );
            mag.rotation.x = 0.55 * drop;
            mag.rotation.z = 0.22 * drop;
          } else {
            mag.visible = true;
            const over = 0.028;
            let yOff;
            if (progress < 0.64) yOff = -dropY * (1 - insert) + over * insert;
            else yOff = over * (1 - insertSettle);
            mag.position.set(bp.x, bp.y + yOff, bp.z);
            mag.rotation.x = 0.12 * (1 - Math.max(insert, insertSettle));
            mag.rotation.z = 0;
          }
        }
      } else if (currentWeapon === 'pistol') {
        // RH stays in idle grip pose — gun parented to gripR must NOT tumble.
        // Only a slight muzzle-up tip for magwell access; LH does mag + slide work.
        const present = _seg(progress, 0.0, 0.18);
        const recover = _seg(progress, 0.90, 1.0);
        const tilt = present * (1 - recover);

        const drop = _seg(progress, 0.10, 0.32);
        const holdGone = progress >= 0.30 && progress < 0.42;
        const insert = _seg(progress, 0.42, 0.68);
        const insertSettle = _seg(progress, 0.68, 0.74);

        const fetchDown = _pulse(progress, 0.28, 0.36, 0.44);
        const fetchUp = _seg(progress, 0.38, 0.48);
        const slap = _pulse(progress, 0.55, 0.64, 0.72);
        const rackPull = _seg(progress, 0.72, 0.88);
        const rackFwd = _seg(progress, 0.88, 0.96);
        const slideAmt = rackPull * (1 - rackFwd);
        const rackHand = _pulse(progress, 0.70, 0.80, 0.96);

        if (!reloadSlideCuePlayed && progress >= 0.72) reloadSlideCuePlayed = true;
        // Eject world mag once when drop window begins (~0.12)
        if (!reloadMagDropped && progress >= 0.12) {
          reloadMagDropped = true;
          spawnDroppedMag();
        }

        // Slight tip-back only (no big arm/elbow deltas — those caused a full spin on gripR)
        reloadMountOff.rx = -0.22 * tilt;  // muzzle tips up a little
        reloadMountOff.rz = 0.05 * tilt;   // tiny magwell roll toward LH
        reloadMountOff.y = 0;
        reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
        reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;

        // Left hand: grab → guide → slap → rack
        reloadArmOffL.x = -0.22 * fetchDown - 0.12 * fetchUp - 0.08 * slap - 0.18 * rackHand;
        reloadArmOffL.y = 0.12 * fetchDown + 0.06 * fetchUp;
        reloadArmOffL.z = 0.18 * fetchDown + 0.10 * fetchUp + 0.08 * rackHand;
        reloadElbowOffL.x =
          -0.85 * fetchDown - 0.55 * fetchUp - 0.95 * slap - 0.70 * rackHand * rackPull;
        reloadElbowOffL.y = 0.14 * fetchDown + 0.08 * rackHand;
        reloadElbowOffL.z = 0.10 * fetchUp - 0.12 * slap;

        const base = GUN_BASE.pistol;
        if (base) {
          gun.position.copy(base.pos);
          gun.rotation.copy(base.rot);
        }

        // Frame/barrel stay planted on the receiver for the whole rack — never move
        // with the slide (that was the fire-detach bug). Slide may still travel.
        if (gun.userData.frame) {
          gun.userData.frame.position.set(0, 0, 0);
          gun.userData.frame.rotation.set(0, 0, 0);
        }
        if (gun.userData.slide && gun.userData.baseSlidePos) {
          gun.userData.slide.position.set(
            gun.userData.baseSlidePos.x,
            gun.userData.baseSlidePos.y,
            gun.userData.baseSlidePos.z - 0.13 * slideAmt
          );
        }
        if (gun.userData.mag && gun.userData.baseMagPos) {
          const mag = gun.userData.mag;
          const bp = gun.userData.baseMagPos;
          const dropY = 0.38;
          if (holdGone) {
            mag.visible = false;
            mag.position.set(bp.x, bp.y - dropY, bp.z + 0.04);
            mag.rotation.x = 0;
            mag.rotation.z = 0;
          } else if (progress < 0.30) {
            mag.visible = true;
            mag.position.set(
              bp.x + 0.02 * drop,
              bp.y - dropY * drop,
              bp.z + 0.05 * drop
            );
            mag.rotation.x = 0.65 * drop;
            mag.rotation.z = 0.18 * drop;
          } else {
            mag.visible = true;
            const over = 0.022;
            let yOff;
            if (progress < 0.68) yOff = -dropY * (1 - insert) + over * insert;
            else yOff = over * (1 - insertSettle);
            mag.position.set(bp.x, bp.y + yOff, bp.z);
            mag.rotation.x = 0.12 * (1 - Math.max(insert, insertSettle));
            mag.rotation.z = 0;
          }
        }
      } else if (currentWeapon === 'shotgun') {
        // Tube-fed pump reload — RH locked (pistol playbook). No mag drop / elbow tumble.
        // Phases over dynamic duration (0.45 + need*0.42):
        //   Ready tip 0.00–0.12 | Load shells 0.12–(0.78 or 0.82) | Optional chamber pump if started empty
        const need = Math.max(1, shotgunReloadNeed || 1);
        const startedEmpty = !!shotgunReloadStartedEmpty;
        const loadStart = 0.12;
        const loadEnd = startedEmpty ? 0.78 : 0.88;
        const tip = _seg(progress, 0.0, 0.12) * (1 - _seg(progress, 0.90, 1.0));

        let insertPulse = 0;
        let shellFlash = 0;
        if (progress >= loadStart && progress < loadEnd) {
          const t = (progress - loadStart) / (loadEnd - loadStart);
          const idx = Math.min(need - 1, Math.floor(t * need));
          const local = t * need - idx;
          insertPulse = Math.sin(_clamp01(local) * Math.PI);
          // Flash strongest mid-insert
          shellFlash = insertPulse;
          if (local > 0.5 && idx > reloadInsertCueIdx) { reloadInsertCueIdx = idx; AudioSys.reloadCue('shell'); }
        }

        // Final chambering pump only if tube was empty at start (no live eject)
        let chamberPump = 0;
        if (startedEmpty) {
          const pb = _seg(progress, 0.80, 0.90);
          const pf = _seg(progress, 0.90, 0.98);
          chamberPump = pb * (1 - pf);
          if (!reloadOpenCuePlayed && progress >= 0.80) {
            reloadOpenCuePlayed = true;
            if (AudioSys.shotgunPump) AudioSys.shotgunPump();
          }
          if (!reloadCloseCuePlayed && progress >= 0.90) {
            reloadCloseCuePlayed = true;
            if (AudioSys.shotgunPump) AudioSys.shotgunPump();
          }
        }

        // Modest tip for tube port access — zero RH arm/elbow tumble
        reloadMountOff.rx = -0.14 * tip - 0.04 * insertPulse;
        reloadMountOff.rz = 0.04 * tip;
        reloadMountOff.y = 0.006 * tip;
        reloadArmOff.x = reloadArmOff.y = reloadArmOff.z = 0;
        reloadElbowOffR.x = reloadElbowOffR.y = reloadElbowOffR.z = 0;

        // LH: one-by-one shells into magazine tube (under barrel)
        reloadArmOffL.x = -0.14 * insertPulse - 0.10 * chamberPump - 0.06 * tip;
        reloadArmOffL.y = 0.06 * insertPulse + 0.04 * tip;
        reloadArmOffL.z = 0.12 * insertPulse + 0.08 * chamberPump + 0.05 * tip;
        reloadElbowOffL.x = -0.75 * insertPulse - 0.45 * chamberPump - 0.15 * tip;
        reloadElbowOffL.y = 0.08 * insertPulse;
        reloadElbowOffL.z = 0.10 * insertPulse - 0.05 * chamberPump;

        const base = GUN_BASE.shotgun;
        if (base) {
          gun.position.copy(base.pos);
          gun.rotation.copy(base.rot);
        }

        // Pump stays mostly forward while loading; optional chamber rack at end
        if (gun.userData.pump && gun.userData.basePumpPos) {
          const p = gun.userData.pump;
          p.position.set(
            gun.userData.basePumpPos.x,
            gun.userData.basePumpPos.y,
            gun.userData.basePumpPos.z - 0.12 * chamberPump
          );
        }

