    }

    // A wall: a post at each end (flush to the cell's corners, so two walls meeting at
    // a corner share one), boards between them, a capping beam along the top and two
    // steel bands on the inside face. The boards are cut at the sill into a lower run
    // and an upper run, and the upper run into a left, a middle and a right section:
    // a window takes out the middle upper section — one opening in the middle of the
    // wall — and a door takes out everything between the posts under the cap.
    const WALL_T = 2 * 0.16;          // thickness, post to post
    const WALL_SILL = 0.95;
