    const wallWoodMat = new THREE.MeshStandardMaterial({ color: 0x7a5c38, roughness: 0.85 });
    const wallMetalMat = new THREE.MeshStandardMaterial({ color: 0x555b63, metalness: 0.55, roughness: 0.5 });
    // === Tiered materials ==========================================================
    // Shared across every piece of that tier, so a hundred stone walls are a handful of
    // materials (and the baking merges each wall down to a few meshes per material).
    // Stone and steel are two shared materials whose shade rides in the vertex colours,
    // so a stone wall of three block tones, mortar and dark coping bakes down to ONE
    // draw call instead of five. `tint(vc, hex)` is a shade of one of them; _mesh()
    // paints the shade into the geometry.
    const stoneVC = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, vertexColors: true });
    const steelVC = new THREE.MeshStandardMaterial({ color: 0xffffff, metalness: 0.68, roughness: 0.42, vertexColors: true });
    const tint = (vc, hex) => ({ vc, color: new THREE.Color(hex), isTint: true });
