    // What the reticle says about a placement: the level and the piece it is on.
    function placeOpts(pt) {
      // Honour elevated lv from getPlacePoint even when the thin wall mesh was not
      // hit (ray height over a walled cell). Drag already kept pt.lv; tryPlace/ghost
      // must too, or wall-top aim quietly boardwalks (D-12 / GB-8).
      if (!pt) return null;
      if (pt.hit) return { lv: pt.lv, piece: pt.hit };
      if (pt.lv != null) return { lv: pt.lv };
      return null;
    }
    function tryPlace() {
      if (!placeMode || !gameStarted || gameOver || won) return;
      if (placeMode === 'upgrade') { tryUpgrade(); return; }
      const pt = getPlacePoint();
      const opts = placeOpts(pt);
      const why = placeRefusal(pt.x, pt.z, pt.gx, pt.gz, buildYaw, opts);
      // GB-62 (P-3): why it will not go, then the Cash, then anything else the ghost knows.
      // Short of Cash used to read "CAN'T BUILD THERE - No room" on open ground.
      const canNot = (sub) => { AudioSys.invalid(); showBanner(sayText('build.message.cannotBuild', null, 'CAN\u0027T BUILD THERE'), sub, 1.2, '#ffb347'); };
      if (why) { canNot(refusalText(why)); return; }
      const carrying = mortarCarried && placeMode === 'mortar';
      if (!carrying && placeMode !== 'shovel' && bank < COST[placeMode]) {
        AudioSys.invalid();
        showBanner(sayText('build.message.insufficient', null, 'NOT ENOUGH CASH'),
          sayText('build.message.cost', { name: BUILD_NAMES[placeMode], cost: COST[placeMode] }, BUILD_NAMES[placeMode] + ' costs $' + COST[placeMode]), 1.1, '#ffb347');
        return;
      }
      // The shovel's first swing at a fence or a camp is free, so only its paid dig needs the Cash.
      if (!ghostValid && placeMode !== 'shovel') { canNot(refusalText('no room')); return; }
      if (carrying) { setDownMortar(pt.x, pt.z); return; }
      if (placeMode === 'shovel') {
        // Something standing in the square gets the shovel first (free): a fence, a
        // camp, a shed. Its rubble, once down, is shovelled away the same way.
        const lmHere = landmarkInSquare(pt.x, pt.z, BUILD_GRID / 2, false);
        if (lmHere && lmHere !== tower) {
          damageLandmark(lmHere, SHOVEL_LANDMARK_DMG, true);
          spawnChunks(pt.x, sampleHeight(pt.x, pt.z) + 0.6, pt.z, lmHere.debrisColor || 0x6b5a3e, 5, 3);
          AudioSys.rockBreak(); addShake(0.05);
          if (lmHere.alive) showBanner('SHOVEL', 'Keep at it — ' + Math.ceil(lmHere.hp) + ' left', 0.9, '#c8a86a');
          updateGhostPreview();
          return;
        }
        if (landmarkInSquare(pt.x, pt.z, BUILD_GRID / 2, true)) {
          clearRubbleInSquare(pt.x, pt.z, BUILD_GRID / 2);
          showBanner('RUBBLE CLEARED', '', 1.0, '#c8a86a');
          AudioSys.buildSound('shovel');
          updateGhostPreview();
          return;
        }
