          AudioSys.invalid();
          showBanner(sayText('build.message.insufficient', null, 'NOT ENOUGH CASH'),
            sayText('build.message.cost', { name: BUILD_NAMES.shovel, cost: COST.shovel }, BUILD_NAMES.shovel + ' costs $' + COST.shovel), 1.1, '#ffb347');
