        // the whole column, bottom up. This used to drop EVERY nearby piece to ground
        // height, so digging beside a wall put its platform, and the turret on it, down
        // on the grass while the walkable deck stayed floating where they had been.
        for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) reseatColumn(pt.gx + dx, pt.gz + dz);
        spawnDust(pt.x, sampleHeight(pt.x, pt.z) + 0.3, pt.z, 7);
