    // World box around one piece, as it is actually drawn.
    function buildAabb(b) {
      const y0 = b.mesh.position.y, rule = ruleFor(b.type), G2 = BUILD_GRID / 2;
      const h = rule && rule.ramp ? (b.rise || LEVEL_H) : Math.max(0.2, pieceHeight(b.type));
      if (rule && (rule.deck || rule.ramp)) {
        return { x0: b.x - G2, x1: b.x + G2, z0: b.z - G2, z1: b.z + G2, y0: rule.deck ? Math.min(y0, y0 + h - 0.25) : y0, y1: y0 + h };
      }
      const thin = thinBoxFor(b);
      if (thin) return { x0: thin.cx - thin.hx, x1: thin.cx + thin.hx, z0: thin.cz - thin.hz, z1: thin.cz + thin.hz, y0, y1: y0 + h };
      const box = linkBoxOf(b);
      if (box) {
        const r = { x0: b.x - box.hz, x1: b.x + box.hz, z0: b.z - box.hz, z1: b.z + box.hz, y0, y1: y0 + h };
        const arms = b.mesh.userData.arms;
        if (arms) {
          const turns = ((Math.round(b.yaw / (Math.PI / 2)) % 4) + 4) % 4;
          for (let d = 0; d < 4; d++) {
            if (!arms[(d - turns + 4) % 4].visible) continue;
            const [dx, dz] = PANEL_DIRS[d];
            if (dx > 0) r.x1 = b.x + G2; if (dx < 0) r.x0 = b.x - G2;
            if (dz > 0) r.z1 = b.z + G2; if (dz < 0) r.z0 = b.z - G2;
          }
        }
        return r;
      }
      const rr = Math.max(0.3, b.radius || 0.5);
      return { x0: b.x - rr, x1: b.x + rr, z0: b.z - rr, z1: b.z + rr, y0, y1: y0 + h };
    }
    // The piece and everything that comes down with it if it goes.
    function scrapSet(b) { return [b].concat(dependentsOf(b)); }
    // === Scrapping a whole box of squares ============================================
    // Hold X, press and drag: every piece in the box of squares on the marine's own
    // storey (or, if there is nothing on it, every piece in the box) is outlined, and
    // letting go of the mouse scraps the lot for the usual refund.
    let scrapDrag = null;          // { gx, gz } the press started on
    let scrapDragUsed = false;     // so letting go of X afterwards does not scrap once more
    const SCRAP_BOX_MAX = 12;      // squares per side
    function scrapBoxPieces(pt) {
      const x0 = Math.max(Math.min(scrapDrag.gx, pt.gx), pt.gx - SCRAP_BOX_MAX), x1 = Math.min(Math.max(scrapDrag.gx, pt.gx), pt.gx + SCRAP_BOX_MAX);
      const z0 = Math.max(Math.min(scrapDrag.gz, pt.gz), pt.gz - SCRAP_BOX_MAX), z1 = Math.min(Math.max(scrapDrag.gz, pt.gz), pt.gz + SCRAP_BOX_MAX);
      const G2 = BUILD_GRID / 2;
      const wx0 = gridCentre(x0) - G2, wx1 = gridCentre(x1) + G2, wz0 = gridCentre(z0) - G2, wz1 = gridCentre(z1) + G2;
      const inBox = [], band = storeyBand();
      for (const b of builds) {
        if (b.gx == null) continue;
        const m = edgeMid(b);
        if (m.x < wx0 || m.x > wx1 || m.z < wz0 || m.z > wz1) continue;
        inBox.push(b);
      }
      const onStorey = inBox.filter((b) => {
        const y0 = b.mesh.position.y, y1 = y0 + (b.rise || Math.max(0.2, pieceHeight(b.type)));
        return y1 > band[0] && y0 < band[1];
      });
      return { pieces: onStorey.length ? onStorey : inBox, box: { x0: wx0, x1: wx1, z0: wz0, z1: wz1 } };
    }
    function scrapBoxSet(pieces) {
      const all = [];
      for (const b of pieces) for (const o of scrapSet(b)) if (all.indexOf(o) < 0) all.push(o);
      return all;
    }
    function commitScrapDrag() {
      if (!scrapDrag || !placeMode) { scrapDrag = null; return; }
      scrapDragUsed = true;
      const { pieces } = scrapBoxPieces(getPlacePoint());
      scrapDrag = null;
      const all = scrapBoxSet(pieces);
      if (!all.length) { AudioSys.invalid(); showBanner('NOTHING THERE', 'Drag over the pieces you want to scrap', 1.1, '#ffb347'); return; }
      let refund = 0;
      for (const o of all) {
        const spent = (o.gift ? 0 : (COST[o.type] || 5)) + (o.opening ? (COST[o.opening] || 0) : 0) + (o.upgradeSpent || 0);
        refund += (spent > 0 ? Math.max(1, Math.ceil(spent * 0.6 * (o.hp / o.maxHp))) : 0);
      }
      for (const b of pieces) if (builds.indexOf(b) >= 0) { spawnDust(b.x, b.mesh.position.y + 0.5, b.z, 3); removeBuild(b); }
      bank += refund;
