    }
    // GB-115 (Jerry, 2026-09-30): a gift (the ranger's turret, GB-91) cost nothing, so scrapping it pays nothing back;
    // only upgrades bought on it refund. The same rule is in the box-scrap preview and commit.
    function scrapRefund(b) {
      let sum = 0;
      for (const o of scrapSet(b)) {
        const spent = (o.gift ? 0 : (COST[o.type] || 5)) + (o.opening ? (COST[o.opening] || 0) : 0) + (o.upgradeSpent || 0);
        sum += (spent > 0 ? Math.max(1, Math.ceil(spent * 0.6 * (o.hp / o.maxHp))) : 0);
      }
      return sum;
    }
    // What X (or T) acts on in build mode: the piece under the reticle, within reach;
    // failing that, the top of the cell the ghost is in.
    // GB-63 (P-4): his own storey only. It used to fall back to any piece on the ray and
    // to the top of the cell, so from the ground X took the deck overhead.
    function scrapTarget() {
      const hit = pickOnMyStorey();
      if (hit && Math.hypot(hit.x - player.position.x, hit.z - player.position.z) <= BUILD_REACH + 1.5 && onMyStorey(hit)) return hit;
      const pt = getPlacePoint();
