          const u = buildAabb(set[0]);
          for (let i = 1; i < set.length; i++) {
            const a = buildAabb(set[i]);
            u.x0 = Math.min(u.x0, a.x0); u.x1 = Math.max(u.x1, a.x1);
            u.y0 = Math.min(u.y0, a.y0); u.y1 = Math.max(u.y1, a.y1);
            u.z0 = Math.min(u.z0, a.z0); u.z1 = Math.max(u.z1, a.z1);
          }
