          (set.length > 1 ? ' + ' + (set.length - 1) + ' on it' : '') + ' → +$' + scrapRefund(b);
      }
      if (hint !== scrapHint) { scrapHint = hint; if (!mortarCarried) refreshPlaceBanner(); }
    }


    // --- Zombies: 5 outbreak types ---
    const zombies = [];
    // How many can be on the field at once — the density knob for the 10x horde. Nudged
    // from 36 to 48 so a ten-times-longer wave reads as a bigger crowd and not just a
    // longer trickle. 48 and not more: with the whole field piled on the player, 90 cost
    // over half the frame rate against 36, while 36 vs 48 was inside the noise. (Those
    // A/Bs were taken in the desktop app's preview pane, which is not a usable absolute
    // benchmark — the *unmodified* build measures ~9.5fps there at its own 36 cap — so
    // only the large gaps are trustworthy. Judge the real numbers from the launcher.)
    const MAX_ZOMBIES = 48;
    // Pooled per type. A single shared pool meant a mismatched mesh was dropped on the
    // floor (never disposed, never reused) every time the wave mix changed.
    const zombiePool = new Map();
    function poolFor(typeKey) {
      let list = zombiePool.get(typeKey);
      if (!list) { list = []; zombiePool.set(typeKey, list); }
      return list;
