    const CLIMB_HEIGHT = 1.1; // climbers vault builds / solids at or under this height
    const CAVE_ROLES = {
      wet:   { trait: 'douse',    speedMul: 0.85, fireResistAdd: 0.22, douseRadius: 1.8, douseAgePerSec: 2.4 },
