      if (typeKey === 'military') { torsoW = 0.52 * s; torsoH = 0.52 * s; torsoD = 0.34 * s; }
      if (typeKey === 'spitter') { torsoW = 0.56 * s; torsoH = 0.52 * s; torsoD = 0.4 * s; }
