      if (typeKey === 'leaper') { torsoW = 0.34 * s; torsoH = 0.62 * s; torsoD = 0.28 * s; }
      if (typeKey === 'drowned') { torsoW = 0.5 * s; torsoH = 0.54 * s; torsoD = 0.36 * s; }
