      hips.add(pelvis);

      // Arms
      const armLG = new THREE.Group();
      const armRG = new THREE.Group();
      const shoulderY = 0.42 * s;
      const shoulderX = (typeKey === 'brute' || typeKey === 'demon' ? 0.42 : 0.32) * s;
      armLG.position.set(-shoulderX, shoulderY, 0);
      armRG.position.set(shoulderX, shoulderY, 0);
      torso.add(armLG, armRG);

      function buildArm(parent, side, droop) {
        const upper = new THREE.Mesh(
          rbox((typeKey === 'brute' || typeKey === 'demon' ? 0.18 : 0.13) * s, 0.36 * s, 0.14 * s),
