        upper.castShadow = true;
        parent.add(upper);
        const elbowG = new THREE.Group();
        elbowG.position.y = -0.34 * s;
        parent.add(elbowG);
        const fore = new THREE.Mesh(
          rbox((typeKey === 'feral' ? 0.1 : 0.12) * s, 0.34 * s, (typeKey === 'feral' ? 0.1 : 0.12) * s),
          skin.clone()
        );
        fore.position.y = -0.14 * s;
        fore.castShadow = true;
        elbowG.add(fore);
        if (typeKey !== 'feral') {
          const hand = new THREE.Mesh(rbox(0.11 * s, 0.1 * s, 0.07 * s, 0.025 * s), skin.clone());
          hand.position.set(0, -0.34 * s, 0.01 * s);
          hand.castShadow = true;
          elbowG.add(hand);
          // Curled fingers as one ridge (kept to a single mesh per hand for draw-call sake).
          const fingers = new THREE.Mesh(rbox(0.1 * s, 0.05 * s, 0.045 * s, 0.015 * s), skin.clone());
          fingers.position.set(0, -0.41 * s, 0.035 * s);
          fingers.rotation.x = 0.5;
          elbowG.add(fingers);
        }
        if (typeKey === 'feral') {
          // Claws
          for (let c = 0; c < 3; c++) {
            const claw = new THREE.Mesh(
              rbox(0.03 * s, 0.16 * s, 0.03 * s),
              new THREE.MeshStandardMaterial({ color: 0x1a1a14, roughness: 0.6, metalness: 0.2 })
