          for (let s = 1; s < P && q < 0; s++) {
            if (p + s < P && spreadBy[p + s].length + packN(p + s) < sizes[p + s]) q = p + s;
            else if (p - s >= 0 && spreadBy[p - s].length + packN(p - s) < sizes[p - s]) q = p - s;
          }
          if (q < 0) break;
