        if (r < 0.5) return 'shambler';
        if (r < 0.7) return 'feral';
        if (r < 0.85) return 'drowned';
        return 'brute';
      }
      const weights = [
        ['shambler', Math.max(0.12, 0.32 - dayNum * 0.025)],
        ['feral', 0.2 + Math.min(0.08, dayNum * 0.008)],
        ['leaper', 0.16],
        ['drowned', 0.1],
        ['spider', dayNum >= 5 ? 0.06 + Math.min(0.06, (dayNum - 5) * 0.01) : 0],
