        reactToHit(o, 'crush', 0, c.dirX, c.dirZ, o.mesh.position.y + (o.hitH || 1.4) * 0.5, CORPSE_CRUSH_RAW);
        return;
      }
    }
    function corpseMove(c, x, z, dt) {
      const m = c.mesh, ox = m.position.x, oz = m.position.z;
      const slid = resolveHardBuildCollisions(x, z, c.radius, false, m.position.y, null);
      m.position.x = slid.x; m.position.z = slid.z;
      corpseShove(c, m.position.x - ox, m.position.z - oz, dt);
    }
    function freezeCorpse(c) {
      if (c.frozen) return;
      c.frozen = true; c.frozenAt = c.t; motionStats.frozen++;
      c.frozenBy = !c.body ? 'topple' : (c.body.sleeping ? (c.settled ? 'settled' : 'pool') : 'time');
      if (c.body && !c.body.sleeping) c.body.sleep();
      const m = c.mesh;
      m.updateMatrixWorld(true);
      m.traverse((o) => { if (o !== m && o.matrixAutoUpdate) { o.updateMatrix(); o.matrixAutoUpdate = false; o.userData._corpseFrozen = true; } });
    }
    function stepCorpseBody(c, dt) {
      const b = c.body, m = c.mesh;
      if (b.sleeping || b.state !== 'dead') { freezeCorpse(c); return; }
      b.follow();
      const ev = b.update(dt);
      b.apply();
      corpseMove(c, m.position.x + b.drift.x, m.position.z + b.drift.z, dt);
      if (ev.some((e) => e[0] === 'settled')) c.settled = true;
      if (b.sleeping || c.t > CORPSE_SETTLE_MAX) freezeCorpse(c);
    }
    function finishCorpse(c) {
      scene.remove(c.pool);
      const mesh = c.mesh;
      if (c.castersOff) for (const o of c.casters) o.castShadow = true; // the pooled mesh goes back whole
      if (c.frozen) mesh.traverse((o) => { if (o.userData._corpseFrozen) { o.matrixAutoUpdate = true; o.userData._corpseFrozen = false; } });
      if (c.body) { releaseBody(c.body); c.body = null; }
      mesh.visible = false;
      scene.remove(mesh);
      mesh.rotation.set(0, c.yaw, 0);
      resetZombieMesh(mesh);
      poolFor(c.typeKey).push(mesh);
    }
    function clearCorpses() {
      for (const c of corpses.splice(0)) finishCorpse(c);
    }
    function updateCorpses(dt) {
      for (let i = corpses.length - 1; i >= 0; i--) {
        const c = corpses[i];
        c.t += dt;
        const m = c.mesh, ud = m.userData;
        const u = Math.min(1, c.t / c.fallT);
        const fall = 1 - Math.pow(1 - u, 2.6);
        const after = c.t - c.fallT;
        if (c.body && !c.frozen) stepCorpseBody(c, dt);
        else if (!c.frozen) {
        if (c.slide && c.t - dt < 0.3) {
          const t0 = Math.max(0, c.t - dt), t1 = Math.min(0.3, c.t), v0 = 2 * c.slide / 0.3;
          const d = v0 * ((t1 - t0) - (t1 * t1 - t0 * t0) / 0.6);
          corpseMove(c, m.position.x + c.dirX * d, m.position.z + c.dirZ * d, dt);
        }
        const bounce = (after > 0 && after < 0.32) ? Math.sin(after / 0.32 * Math.PI) * 0.07 : 0;
        const ang = (Math.PI / 2 - 0.1) * fall + bounce;
        // Topple about the horizontal axis perpendicular to the fall direction (in
        // the body's frame), with a little roll about its own length: yaw * fall * twist.
        _cq1.setFromAxisAngle(_cAxis.set(0, 1, 0), c.yaw);
        _cq2.setFromAxisAngle(_cAxis.set(c.lz, 0, -c.lx).normalize(), ang);
        _cq3.setFromAxisAngle(_cAxis.set(0, 1, 0), c.twist * fall);
        m.quaternion.copy(_cq1).multiply(_cq2).multiply(_cq3);
        // Limbs flail on the way down, then go slack.
        const flail = Math.sin(Math.min(1, u) * Math.PI);
        const p = c.parts;
        if (ud.armLG && !p.armL) { ud.armLG.rotation.x = -1.3 * flail - 0.25 * fall; ud.armLG.rotation.z = 0.35 * fall + 0.4 * flail; }
        if (ud.armRG && !p.armR) { ud.armRG.rotation.x = -1.1 * flail - 0.2 * fall; ud.armRG.rotation.z = -0.3 * fall - 0.4 * flail; }
        if (ud.legLG && !p.legL) { ud.legLG.rotation.x = 0.25 * flail - 0.15 * fall; if (ud.legLG.userData.shinG) ud.legLG.userData.shinG.rotation.x = 0.5 * fall; }
        if (ud.legRG && !p.legR) { ud.legRG.rotation.x = -0.2 * flail + 0.1 * fall; if (ud.legRG.userData.shinG) ud.legRG.userData.shinG.rotation.x = 0.3 * fall; }
        if (ud.head && !p.head) { ud.head.rotation.x = -0.4 * flail + 0.15 * fall; ud.head.rotation.z = 0.35 * fall; }
        if (ud.torso) { ud.torso.rotation.x = 0.1 * flail; ud.torso.rotation.z = 0.12 * fall; ud.torso.rotation.y = 0; }
        // Landed and done bouncing: nothing moves any more.
        if (after > 0.4 && c.t >= 0.3) freezeCorpse(c);
        }
        // Eyes go dark as the body settles.
        if (ud.eyeMats && after > 0) for (const em of ud.eyeMats) em.emissiveIntensity = Math.max(0, 1.7 - after * 1.8);
        if (after > 0.35 && !c.castersOff) { c.castersOff = true; for (const o of c.casters) o.castShadow = false; }
        // The pool spreads once the body is down (a reacting body: once it has settled), where it lies.
        const poolAt = c.body ? (c.frozen ? c.frozenAt : CORPSE_SETTLE_MAX) : c.fallT * 0.75;
        if (!c.pool.visible && (c.body || c.slide)) c.pool.position.set(m.position.x + c.lx * 0.2, sampleHeight(m.position.x, m.position.z) + 0.05, m.position.z + c.lz * 0.2);
        if (c.t > poolAt) {
          c.pool.visible = true;
          c.pool.scale.setScalar(Math.max(0.01, c.poolR * Math.min(1, (c.t - poolAt) / 2.4)));
        }
        // Sink away at the end.
        if (after > CORPSE_LIE) {
          const s = (after - CORPSE_LIE) / 1.6;
          m.position.y = c.baseY - s * 1.3;
          c.pool.scale.setScalar(Math.max(0.01, c.poolR * (1 - s)));
          if (s >= 1) { finishCorpse(c); corpses.splice(i, 1); }
        }
      }
    }

    function killZombie(z, award = true, deathInfo = null) {
      if (!z.alive) return;
      z.alive = false;
      if (z.fogHidden && z.mesh) { z.fogHidden = false; z.mesh.visible = true; }   // GB-59: the corpse is his to walk up to
      motionZs.delete(z);   // GB-66: a corpse takes the body over (beginCorpse); a gib gives its slot back below
      // GP-38 (ChatGPT's request): the last guard of a POI down is a cleared site, once per post.
      // retirePoiGuards (the alarm) and clearZombies (resets) never come through here, so neither is a clear.
      if (z.poiGuard && !z.poiGuard.cleared && !zombies.some((o) => o !== z && o.alive && o.poiGuard === z.poiGuard)) {
        z.poiGuard.cleared = true;
        publishUI('poi-cleared', { kind: z.poiGuard.kind, index: z.poiGuard.index, x: z.poiGuard.x, z: z.poiGuard.z, count: z.poiGuard.n || 0 });
        if (z.poiGuard.bounty) settleBounty(z.poiGuard);   // GB-57: the reward, after its poi-cleared
      }
      const info = deathInfo || { kind: 'generic', dir: { x: 0, z: 0 }, defense: true };
      const kind = info.kind || 'generic';
      const dx = (info.dir && info.dir.x) || 0;
      const dz = (info.dir && info.dir.z) || 0;
      const px = z.mesh.position.x, py = z.mesh.position.y, pz = z.mesh.position.z;
      const skin = z.mesh.userData.skinColor || 0x8a7a60;
      const eye = z.mesh.userData.eyeColor || 0x88ff44;
      const hitY = py + (z.hitH || 1.4) * 0.55;
      if (!z.partsLost) z.partsLost = emptyPartsLost();

      if (kind === 'explosive') {
        if (z.body) releaseBody(z.body);
        spawnBlood(px, hitY, pz, dx, dz, 26, 2.0);
        spawnGibBurst(px, hitY, pz, skin, eye, dx, dz, 'explosive');
        // Full body gib — fling remaining limbs then dispose mesh
        for (const k of PART_KEYS) {
          if (!z.partsLost[k]) detachZombiePart(z, k, dx + (Math.random() - 0.5), dz + (Math.random() - 0.5));
        }
        z.mesh.userData.gibbed = true;
        z.mesh.userData.dismembered = true;
        recycleOrDisposeZombie(z, true);
      } else if (kind === 'chainsaw') {
        if (z.body) releaseBody(z.body);
        spawnBlood(px, hitY, pz, dx, dz, 22, 1.7);
        spawnGibBurst(px, hitY, pz, skin, eye, dx, dz, 'chainsaw');
        // Heavy meat spray along blade dir + sequential remaining limbs
        for (const k of PART_KEYS) {
          if (!z.partsLost[k] && Math.random() < 0.85) detachZombiePart(z, k, dx, dz);
        }
        z.mesh.userData.gibbed = true;
        z.mesh.userData.dismembered = true;
        recycleOrDisposeZombie(z, true);
      } else if (kind === 'pellet') {
        spawnBlood(px, hitY, pz, dx, dz, 18, 1.5);
        spawnGibBurst(px, hitY, pz, skin, eye, dx, dz, 'pellet');
        if (Math.random() < 0.65) {
          const avail = PART_KEYS.filter((k) => !z.partsLost[k]);
          if (avail.length) detachZombiePart(z, avail[(Math.random() * avail.length) | 0], dx, dz);
        }
        if (!beginCorpse(z, dx, dz, info)) recycleOrDisposeZombie(z, z.mesh && z.mesh.userData.dismembered);
      } else if (kind === 'melee') {
        spawnBlood(px, hitY, pz, dx, dz, 8, 0.9);
        if (!beginCorpse(z, dx, dz, info)) recycleOrDisposeZombie(z, z.mesh && z.mesh.userData.dismembered);
      } else {
        // bullet / generic — tumble with 1–2 parts
        spawnBlood(px, hitY, pz, dx, dz, 14, 1.25);
        const nParts = 1 + ((Math.random() < 0.45) ? 1 : 0);
        const avail = PART_KEYS.filter((k) => !z.partsLost[k]);
        for (let n = 0; n < nParts && avail.length; n++) {
          const ix = (Math.random() * avail.length) | 0;
          const k = avail.splice(ix, 1)[0];
          detachZombiePart(z, k, dx, dz);
        }
        if (Math.random() < 0.25) spawnFleshChunks(px, hitY, pz, dx, dz, skin, 2);
        if (!beginCorpse(z, dx, dz, info)) recycleOrDisposeZombie(z, z.mesh && z.mesh.userData.dismembered);
      }

      const i = zombies.indexOf(z);
      if (i >= 0) zombies.splice(i, 1);
      // CL-26: the last kill of a wave gets the finisher.
      if (phase === 'wave' && waveSpawned >= waveTotal && !gameOver && !won && !zombies.some((o) => o.alive)) {
        try { beginWaveFinisher(z, px, py, pz); } catch (_) {}
      }
      if (award) {
        matchStats.kills += 1;
        // Only the marine's own kills feed the kill streak: what a turret, a mine, a
        // spike trap or a strand of wire takes down still pays, but at the base rate.
        const mult = info.defense ? 1 : registerKill();
        z._defenseKill = false;
        const rawCash = (z.cashDrop != null ? z.cashDrop : (z.reward || 2)) * mult * cashMult() * lateCashMul();
        const payMul = nightPayMul();   // GB-82: blood moon x1.5, the Lights out dare x1.25, both together at most x1.75
        if (hqBlackout) dareEarned += rawCash * (payMul - (bloodMoon ? 1.5 : 1));
        const cash = skullLedger.credit(rawCash * payMul);   // GP-33: fractions carry
        skullValueTotal += cash;
        awardCash(px, pz, cash, z.typeKey, py);   // GB-60: py, so a skull from the tunnel comes out of it
        if (Math.random() < medDropChance(z.typeKey)) spawnMedDrop(px + 0.6, pz + 0.4);
        {
          const sa = sndAt(px, pz);
          AudioSys.zombieDeath(sa.v, sa.pan, z.typeKey === 'brute' || z.typeKey === 'demon' || z.typeKey === 'colossus' || z.typeKey === 'guardian');
        }
        if (z.typeKey === 'colossus') {
          showBanner(dwText('wave.colossusDown'), dwText('wave.colossusReward', { value: cash }), 3.2, '#ffd24a');
          addShake(0.45);
          triggerSlowMo(1.1);
        }
        if (z.typeKey === 'guardian') {
          if (z.cavePoke) publishCaveGuardian(z.caveIndex, px, pz, 'death');
          showBanner(dwText(GUARDIAN_KEYS.name).toUpperCase() + ' DOWN', '+$' + cash + ' in skulls — turn them in at HQ', 3.2, '#bdf3ff');
          addShake(0.4);
          triggerSlowMo(1.0);
          // First-blood: only a planned guardian from a guardian night (never debug spawn).
          // Combat proposes; ChatGPT economy owns receipt/grant (no direct Cash). D-16 / GB-17.
          const playerCredit = !info.defense;
          const plannedGuardian = !!z.guardianPlanned;
          if (playerCredit && plannedGuardian && !guardianFirstBloodDone) {
            guardianFirstBloodDone = true;
            publishUI('guardian-first-blood', {
              receiptId: 'guardian-night-first',
              typeKey: 'guardian',
              playerCredit: true,
              planned: true,
              x: px,
              z: pz,
              propose: 'mortar-blueprint-or-80-skulls',
              keys: Object.assign({}, GUARDIAN_KEYS),
              titleKey: GUARDIAN_KEYS.firstBlood,
              blueprintKey: GUARDIAN_KEYS.blueprint,
              skullsKey: GUARDIAN_KEYS.skulls,
              bonusSkullValue: 80
            });
          }
          publishUI('guardian-killed', {
            typeKey: 'guardian',
            playerCredit,
            planned: plannedGuardian,
            cash,
            firstBloodDone: !!guardianFirstBloodDone,
            keys: Object.assign({}, GUARDIAN_KEYS)
          });
        }
      }
      // A bomber's payload goes off no matter how it died.
      if (z.typeKey === 'bomber' && !z._detonated) {
        z._detonated = true;
        // GB-77 (P-28): his kill (a shot, his blade, his fire, or a blast he set off) is his chain too.
        bomberBlast(px, py + 0.7, pz, !info.defense && !info.selfBlast);
      }
    }

    function clearZombies() {
      for (const z of zombies.slice()) {
        z.alive = false;
        if (z.mesh) {
          z.mesh.visible = false;
          scene.remove(z.mesh);
          resetZombieMesh(z.mesh);
          poolFor(z.typeKey).push(z.mesh);
        }
      }
      zombies.length = 0;
      clearCorpses();
    }

    // --- Day / wave system ---
    let day = 0;
    let phase = 'idle';
    let prepTimer = 0;
    let waveTotal = 0;
    let poiGuardsDue = false;   // GB-43: day-1 POI guards waiting to be placed
    let waveSpawnLog = [];   // GB-40: where each wave body came from (tests)
    let waveSpawned = 0;
    let spawnCd = 0;
    let zombiesRemaining = 0;
    const PREP_TIME = 120; // was 12 — a real window to shop, build and reposition in
    const HOUSE_SPAWN_EXCLUSION = 30.5; // metres — about 100 feet

    let waveQueue = [];
    let caveByIndex = []; // parallel to waveQueue: POI.caves index or -1 (drowned)
    let wavePreview = null; // frozen WavePreview for current prep/wave day
    let burstLeft = 0;
    let ambushCd = 0;
    // GB-53: the night's pushes and the breathers between them (see NIGHT_PLAN / NIGHT_TIER).
    let nightPace = null;
    const LULL_FIELD = 5;       // a breather starts its clock once the field is down to this many
    const LULL_MAX_WAIT = 30;   // s; a camper doesn't hold the night up for ever
    const LULL_MAX_SURGE = 45;  // s; GB-71 (P-16): a test night's one breather, before the last push, waits at most this long

    function zombiesForDay(n) {
      // Front-loaded harder than it used to be: the economy runs on kills now, so the
      // first nights need enough bodies to actually buy something with.
      if (n <= 1) return 4;
      if (n === 2) return 7;
      if (n === 3) return 10;
      if (n === 4) return 13;
      return Math.round(9 + n * 2.6 + Math.max(0, n - 5) * 1.6);
    }

    // Direction control: most days the horde comes from announced compass bearings, so
    // there is a front line to build against. Some days it doesn't.
    let waveBearings = [];
    let waveSurround = false;
    let guardianNightActive = false;
    // CU-77 (P-55): what kind of night this is, for 'night-cleared' at dawn. One word, in this order:
    // fog (P-56's mod), swarm (P-98's mod, GB-93), siege (night 18's trick), guardian, colossus, blood-moon (Ember Night), plain.
    let nightKindNow = 'plain', nightClearedDay = 0;
    // GB-88 (P-59): the siege trick (night 18) is live tonight: brutes and soldiers spawn with the 'smash' tactic and go
    // for the nearest placed wall or barricade (within 28 m); with none they come for the marine. Totals, the mix and the
    // guardian's rules are the plan's own. A brute keeps its weight (z.brute) and its 'tank' shove (siegeFrom).
    let siegeNightNow = false;
    const SIEGE_SMASHERS = { brute: 1, military: 1 };
    function nightKindOf(d, plan, guardian) {
      if (plan && plan.mod === 'fog') return 'fog';
      if (plan && plan.mod === 'swarm') return 'swarm';   // GB-93 (P-98): Swarm Night, night 17
      if (plan && plan.trick === 'siege') return 'siege';
      if (guardian) return 'guardian';
      if (d % 5 === 0) return 'colossus';
      if (d >= 4 && d % 4 === 0) return 'blood-moon';
      return 'plain';
    }
    let guardianCaveIndex = -1;
    let guardianFirstBloodDone = false; // per-run receipt; economy owns grant, combat proposes once
    // Canonical GP-10 keys (ChatGPT). Combat references these by name; no hard-coded copy.
    const GUARDIAN_KEYS = {
      name: 'enemy.guardian.name',
      night: 'wavePreview.guardianNight',
      fromCave: 'wavePreview.guardianFromCave',
      urgent: 'wavePreview.guardianUrgent',
      firstBlood: 'reward.guardianFirstBlood',
      blueprint: 'reward.guardianBlueprint',
      skulls: 'reward.guardianSkulls'
    };
    function isGuardianNight(dayNum) {
      const d = dayNum == null ? day : dayNum;
      return d >= 6 && d % 6 === 0;
    }
    function findGuardianCaveIndex() {
      if (!POI.caves || !POI.caves.length) return -1;
      let i = POI.caves.findIndex((c) => c && c.theme === 'chalk');
      if (i < 0) i = POI.caves.findIndex((c) => c && c.theme === 'hill');
      if (i < 0) i = 0;
      return i;
    }
    /** Trim ~20% shambler fodder so guardian + specialists fit under MAX_ZOMBIES. */
    function trimGuardianFodder(mix) {
      const idxs = [];
      for (let i = 0; i < mix.length; i++) if (mix[i] === 'shambler') idxs.push(i);
      const drop = Math.max(1, Math.floor(idxs.length * 0.2));
      const remove = new Set(idxs.slice(-drop));
      return mix.filter((_, i) => !remove.has(i));
    }
    function getGuardianState() {
      if (!wavePreview || !wavePreview.hasGuardian) return null;
      const alive = zombies.find((z) => z.alive && z.typeKey === 'guardian');
      return {
        planned: true,
        alive: !!alive,
        caveIndex: wavePreview.guardianCaveIndex,
        hp: alive ? alive.hp : 0,
        maxHp: alive ? alive.maxHp : (ZOMBIE_TYPES.guardian ? ZOMBIE_TYPES.guardian.hp : 0),
        firstBloodDone: !!guardianFirstBloodDone,
        keys: GUARDIAN_KEYS
      };
    }

    /** Boss pip for ChatGPT minimap (GB-19). null unless a guardian night is planned AND one is alive. */
    function getGuardianAlive() {
      if (!wavePreview || !wavePreview.hasGuardian) return null;
      const alive = zombies.find((z) => z.alive && z.typeKey === 'guardian');
      if (!alive || !alive.mesh) return null;
      return {
        x: alive.mesh.position.x,
        z: alive.mesh.position.z,
        hp: alive.hp,
        hpMax: alive.maxHp,
        caveIndex: (alive.caveIndex != null && alive.caveIndex >= 0) ? alive.caveIndex : wavePreview.guardianCaveIndex
      };
    }


    // === GB-16: objectives combat side ========================================
    // (a) radio defenders once/run; (b) capacity-aware grants; (c) player-damaged
    // event for hold-E interrupt. ChatGPT owns objective UI/state.
    const RADIO_OBJECTIVE_ID = 'objective:radio-repair';
    const RADIO_DEFENDER = {
      id: RADIO_OBJECTIVE_ID,
      // Spec fallback centre (CL-6 / GP-8). Live objectiveProps override when present.
      cx: -149.87, cy: 0.38, cz: -1.15,
      triggerR: 24,
      rMin: 8, rMax: 12,
      minPlayerSep: 8,
      count: 2,
      typeKey: 'shambler'
    };
    let radioDefendersFired = false;
    let radioDefendersPending = false;
    let radioDefendersSpawned = 0;
    const supplyGrantReceipts = Object.create(null);

    function radioCentre() {
      try {
        const props = objectiveProps && objectiveProps.props;
        const p = props && props[RADIO_OBJECTIVE_ID];
        if (p && p.centre) return { x: p.centre.x, y: p.centre.y, z: p.centre.z };
      } catch (_) {}
      return { x: RADIO_DEFENDER.cx, y: RADIO_DEFENDER.cy, z: RADIO_DEFENDER.cz };
    }

    function resetObjectiveCombat() {
      radioDefendersFired = false;
      radioDefendersPending = false;
      radioDefendersSpawned = 0;
      for (const k of Object.keys(supplyGrantReceipts)) delete supplyGrantReceipts[k];
    }

    function isNavValidSpawn(x, z) {
      if (!Number.isFinite(x) || !Number.isFinite(z)) return false;
      if (waterDepthAt(x, z) > 0.35) return false;
      if (terrainSlope(x, z) > 0.55) return false;
      try {
        const k = ffIndexOf(ffPlayer, x, z);
        if (k >= 0 && ffPlayer.blocked[k]) return false;
      } catch (_) {}
      return true;
    }

    function isOutsideImmediateView(x, z) {
      const dx = x - nearestPlayer(0, 0).position.x, dz = z - nearestPlayer(0, 0).position.z;
      const d = Math.hypot(dx, dz) || 1;
      const fx = Math.sin(aimYaw), fz = Math.cos(aimYaw);
      const dot = (dx / d) * fx + (dz / d) * fz;
      return dot < Math.cos(70 * Math.PI / 180);
    }

    function pickRadioDefenderSeat(cx, cz, taken) {
      const px = nearestPlayer(0, 0).position.x, pz = nearestPlayer(0, 0).position.z;
      for (let attempt = 0; attempt < 48; attempt++) {
        const a = Math.random() * Math.PI * 2;
        const r = RADIO_DEFENDER.rMin + Math.random() * (RADIO_DEFENDER.rMax - RADIO_DEFENDER.rMin);
        const x = cx + Math.cos(a) * r;
        const z = cz + Math.sin(a) * r;
        if (Math.hypot(x - px, z - pz) < RADIO_DEFENDER.minPlayerSep) continue;
        if (!isOutsideImmediateView(x, z)) continue;
        if (!isNavValidSpawn(x, z)) continue;
        let clash = false;
        for (const t of taken) if (Math.hypot(x - t.x, z - t.z) < 2.2) { clash = true; break; }
        if (clash) continue;
