          if (caveByIndex.length) caveByIndex.shift();
          // GB-53: the push is out; breathe before the next one.
          if (nightPace && --nightPace.left <= 0 && nightPace.push < nightPace.sizes.length - 1) {
            if (nightPace.straight && nightPace.push < nightPace.sizes.length - 2) {
              // GB-71 (P-16): on a test night the early pushes run straight on into the next one.
              nightPace.push += 1; nightPace.left = nightPace.sizes[nightPace.push];
              publishWavePush(0);
            } else {
              nightPace.inLull = true; nightPace.lullT = nightPace.lull; nightPace.lullWait = 0; burstLeft = 0;
              maybeBreatherCrate(nightPace.push);   // GB-83 (P-45): with the relay up, one crate in a breather
              if (nightPace.straight) warnActiveCaves(1);   // GB-71: the one real breather; the cave eyes dim
            }
          }
        }
      } else {
        // Field full — come straight back rather than burning the burst on nothing.
        spawnCd = 0.35;
        burstLeft += 1;
      }
    }

    // === Supply drops ===
    // A cargo plane crosses the map and kicks a crate out the back. It falls free for a
    // moment, the chute cracks open, and it swings down on its lines; on the ground the
    // canopy folds beside it and a compact white strobe marks the spot. Inside: ammunition for
    // everything you carry, and MedPens. Nothing else.
    const supplyDrops = [];
    const supplyPlanes = [];
    let supplyDropSerial = 0;
    const supplyLightPosition = new THREE.Vector3();
    let supplyCd = 200;
    // GB-81 (P-38, D-49): drops are earned. Until the relay is up: one random crate a night, in the wave, never by
    // day. Once it is up the timer stops, and the day's radio call (and GB-83's breather crate) bring the crates.
    let supplyRandomNight = -1, supplyArmNight = -1, relayUpDbg = null, radioCrateDay = -1;
    const radioCrateReceipts = new Set();
    const RADIO_CRATE = { rMin: 22.5, rMax: 37.5, guardRMin: 6, guardRMax: 10, guardSep: 8 };   // 20-40 m from the mast once the chute drifts its 2.5 m
    function relayUp() {
      if (relayUpDbg != null) return relayUpDbg;
      try { return objectiveRuntime?.read()?.radioCall?.repaired === true; } catch (_) { return false; }
    }
    const crateMat = new THREE.MeshStandardMaterial({ color: 0x5a6b3a, roughness: 0.8 });
    const crateBandMat = new THREE.MeshStandardMaterial({ color: 0x2c3024, roughness: 0.6, metalness: 0.3 });
    const crateStencilMat = new THREE.MeshStandardMaterial({ color: 0xe8e2c8, roughness: 0.7 });
    const airborne = window.createAirborneRig(THREE, sampleHeight);
    const planeMat = new THREE.MeshStandardMaterial({ color: 0x5c6650, roughness: 0.7, metalness: 0.2 });
    const planeDark = new THREE.MeshStandardMaterial({ color: 0x2a2e26, roughness: 0.6 });
    const planeTrim = new THREE.MeshStandardMaterial({ color: 0x6e7862, roughness: 0.62, metalness: 0.25 });
    const planeKeel = new THREE.MeshStandardMaterial({ color: 0x474f3f, roughness: 0.78, metalness: 0.12 });
    const planeMetal = new THREE.MeshStandardMaterial({ color: 0x9aa096, roughness: 0.34, metalness: 0.85 });
    const planeGlass = new THREE.MeshStandardMaterial({ color: 0x0f151a, roughness: 0.14, metalness: 0.7 });
    const planeStencil = new THREE.MeshStandardMaterial({ color: 0xd8d3ba, roughness: 0.7 });
    const planeBayMat = new THREE.MeshStandardMaterial({ color: 0x191d16, roughness: 0.92, side: THREE.DoubleSide });
    // A four-engine turboprop freighter. The detail is aimed at the two angles you actually
    // get: from underneath as she crosses the map, and from behind as the load leaves. So the
    // fuselage is sectioned with a glazed flight deck, the high wing carries flaps, tip lights
    // and drop tanks, gear sponsons run the flanks, and the upswept tail sits over an open bay
    // with the ramp down and the jump lights burning.
    function makeCargoPlane() {
      const g = new THREE.Group();
      // Lamps get their own materials so each aircraft blinks on its own clock; flagging them
      // airborne-owned lets dispose() collect them along with the rest of the model.
      const lamp = (color, intensity) => {
        const m = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: intensity, roughness: 0.4 });
        m.userData.airborneOwned = true; return m;
      };
      const beaconMat = lamp(0xff2a18, 0.3), strobeMat = lamp(0xeef6ff, 0.3), jumpMat = lamp(0xff1d0c, 1.1);
      const navPort = lamp(0xff2a18, 1.4), navStar = lamp(0x2bff72, 1.4);
      // Spinning blades read as a haze rather than four bars; this disc sells that.
      const discMat = new THREE.MeshBasicMaterial({ color: 0x1a1d18, transparent: true, opacity: 0.08, side: THREE.DoubleSide, depthWrite: false });
      discMat.userData.airborneOwned = true;
      const put = (parent, mesh, x, y, z, shadow) => { mesh.position.set(x, y, z); mesh.castShadow = !!shadow; parent.add(mesh); return mesh; };
      const add = (mesh, x, y, z) => put(g, mesh, x, y, z, true);      // structure, worth a shadow
      const deco = (mesh, x, y, z) => put(g, mesh, x, y, z, false);    // trim, too small to matter
      const box = (w, h, d, mat) => new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
      // Cylinders laid along the aircraft's axis; rf is the radius of the forward face.
      const tube = (rf, ra, len, mat, seg = 12, open = false) => {
        const m = new THREE.Mesh(new THREE.CylinderGeometry(rf, ra, len, seg, 1, open), mat);
        m.rotation.x = Math.PI / 2; return m;
      };
      // A curved patch lying on the skin, for doors, windows and paint. Radii follow the
      // section it sits on; `mid` runs from 0 at the keel through Math.PI/2 at the port flank
      // to Math.PI along the spine.
      const patch = (rf, ra, len, mid, arc, mat, seg = 6) => {
        const m = new THREE.Mesh(new THREE.CylinderGeometry(rf, ra, len, seg, 1, true, mid - arc / 2, arc), mat);
        m.rotation.x = Math.PI / 2; return m;
      };

      // --- Fuselage: constant-section barrel, tapered nose, upswept tail boom ---------
      add(tube(1.4, 1.4, 13.4, planeMat, 16, true), 0, 0, 0.6);
      add(tube(1.15, 1.4, 2.7, planeMat, 16), 0, 0, 8.65);
      add(tube(0.62, 1.15, 1.5, planeMat, 16), 0, 0, 10.75);
      // Open at both ends so the eye can follow the bay out through the ramp opening.
      const boom = add(tube(1.4, 1.2, 5.2, planeMat, 16, true), 0, 0.26, -8.7);
      boom.rotation.x = Math.PI / 2 + 0.06;
      // Aft of the ramp hinge only the upper shell remains, so nothing hangs into the opening.
      const beaver = add(patch(1.2, 0.95, 2.0, Math.PI, Math.PI * 0.98, planeMat, 14), 0, 0.62, -12.28);
      beaver.rotation.x = Math.PI / 2 + 0.2;
      const beaverEnd = deco(new THREE.Mesh(new THREE.CircleGeometry(0.9, 14, 0, Math.PI), planeDark), 0, 0.82, -13.12);
      beaverEnd.rotation.y = Math.PI;                                     // its blunt aft face
      deco(box(0.55, 0.14, 11.0, planeKeel), 0, -1.3, 0.6);              // keel strip
      for (const z of [6.4, 3.2, -0.4, -3.6]) deco(patch(1.415, 1.415, 0.07, 0, Math.PI * 2, planeDark, 16), 0, 0, z);

      // --- Flight deck: the windscreen wraps the taper, radome slung underneath ------
      deco(patch(0.68, 1.1, 1.3, Math.PI, 1.8, planeGlass, 8), 0, 0, 10.85);
      deco(patch(0.72, 1.16, 0.16, Math.PI, 1.9, planeDark, 8), 0, 0, 10.14);           // windscreen frame
      deco(patch(0.6, 0.66, 0.18, Math.PI, 1.8, planeDark, 8), 0, 0, 11.45);
      const radome = deco(new THREE.Mesh(new THREE.SphereGeometry(0.66, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2), planeDark), 0, -0.36, 11.15);
      radome.rotation.x = Math.PI / 2; radome.scale.y = 1.35;             // stretched along its own axis
      for (const s of [-1, 1]) {
        deco(patch(1.28, 1.35, 1.5, s * 1.12, 0.4, planeGlass), 0, 0, 8.5);             // glasshouse side panes
        deco(patch(0.78, 0.9, 0.5, s * 0.95, 0.5, planeGlass), 0, 0, 10.75);            // navigator's chin windows
        deco(box(0.05, 0.05, 1.1, planeMetal), s * 0.46, -0.02, 11.85);                 // pitot booms
      }

      // --- Cargo bay: what you see when the load goes out the back -------------------
      deco(box(2.4, 0.16, 7.2, planeBayMat), 0, -0.68, -7.7);            // floor
      deco(box(2.3, 0.1, 7.2, planeBayMat), 0, 1.0, -7.7);               // ceiling
      deco(box(2.5, 1.8, 0.14, planeBayMat), 0, 0.15, -4.1);             // forward bulkhead
      for (const s of [-1, 1]) {
        deco(box(0.1, 1.7, 7.2, planeBayMat), s * 1.18, 0.15, -7.7);     // side walls
        deco(box(0.16, 0.08, 7.0, planeDark), s * 0.72, -0.56, -7.7);    // roller rails
        deco(box(0.07, 0.07, 6.2, planeMetal), s * 0.9, 0.88, -7.9);     // static-line cables
        deco(new THREE.Mesh(new THREE.SphereGeometry(0.11, 8, 6), jumpMat), s * 1.06, 0.66, -10.4);
        deco(new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 6), jumpMat), s * 1.06, 0.66, -8.2);
        deco(patch(1.44, 1.44, 0.95, s * Math.PI / 2, 0.5, planeTrim), 0, 0, -4.6);    // paratroop doors
      }
      deco(patch(1.44, 1.44, 1.0, Math.PI / 2, 0.52, planeTrim), 0, 0, 5.6);   // crew door
      // Ramp, hinged at the aft floor edge and walked all the way down.
      const ramp = add(box(2.34, 0.18, 3.2, planeKeel), 0, -1.16, -12.8);
      ramp.rotation.x = -0.36;
      deco(box(2.34, 0.12, 0.5, planeDark), 0, -1.75, -14.3);            // toe
      for (const s of [-1, 1]) {
        const rail = deco(box(0.1, 0.3, 3.2, planeDark), s * 1.18, -1.02, -12.8);
        rail.rotation.x = -0.36;
        const jack = deco(box(0.11, 0.11, 1.55, planeMetal), s * 0.8, -1.06, -11.9);
        jack.rotation.x = -0.55;                                         // ramp actuators
      }

      // --- Wing: high-mounted, faired into the spine ---------------------------------
      add(box(5.4, 0.8, 3.8, planeMat), 0, 1.5, 1.0);                    // centre-section fairing
      for (const s of [-1, 1]) {
        const w = new THREE.Group(); w.position.set(0, 1.35, 1.0); w.rotation.z = s * 0.04; g.add(w);
        // Straight trailing edge, tapering leading edge: all three panels end at z -1.65.
        put(w, box(9.4, 0.44, 3.3, planeMat), s * 7.4, 0, 0, true);
        put(w, box(3.4, 0.34, 2.6, planeMat), s * 13.8, 0.02, -0.35, true);
        put(w, box(1.0, 0.26, 1.8, planeMat), s * 16.0, 0.04, -0.75, true);
        for (const [len, cx, cz, r] of [[9.4, 7.4, 1.65, 0.22], [3.4, 13.8, 0.95, 0.17]]) {
          const le = put(w, new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8), planeMat), s * cx, 0, cz, true);
          le.rotation.z = Math.PI / 2;                                   // rounded leading edge
        }
        put(w, box(5.6, 0.26, 0.9, planeTrim), s * 4.6, -0.04, -2.05, true);    // inboard flap
        put(w, box(3.0, 0.24, 0.85, planeTrim), s * 9.9, -0.03, -2.02, true);   // outboard flap
        put(w, box(3.0, 0.2, 0.8, planeTrim), s * 13.6, 0, -2.0, false);        // aileron
        put(w, box(2.4, 0.06, 0.5, planeDark), s * 5.0, 0.24, 0.5, false);      // spoiler panel
        put(w, box(0.3, 0.05, 2.6, planeStencil), s * 2.9, 0.24, 0, false);     // walkway line
        put(w, new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 6), s > 0 ? navPort : navStar), s * 16.6, 0.06, -0.3, false);
        put(w, new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), strobeMat), s * 16.45, 0.1, -1.05, false);
        put(w, new THREE.Mesh(new THREE.SphereGeometry(0.14, 8, 6), strobeMat), s * 3.2, -0.2, 1.7, false);  // landing light
        // Drop tank slung between the engines.
        put(w, box(0.3, 0.62, 1.2, planeTrim), s * 6.75, -0.42, 0.4, false);
        put(w, tube(0.5, 0.5, 3.8, planeTrim, 10, true), s * 6.75, -0.78, 0.4, true);
        const tf = put(w, new THREE.Mesh(new THREE.ConeGeometry(0.5, 1.1, 10), planeTrim), s * 6.75, -0.78, 2.85, false);
        tf.rotation.x = Math.PI / 2;
        const tr = put(w, new THREE.Mesh(new THREE.ConeGeometry(0.5, 1.4, 10), planeTrim), s * 6.75, -0.78, -2.2, false);
        tr.rotation.x = -Math.PI / 2;
      }

      // --- Engines: four turboprops with spinners, painted tips and exhaust soot -----
      const props = [];
      for (const x of [-9.4, -4.9, 4.9, 9.4]) {
        const n = new THREE.Group(); n.position.set(x, 1.12, 1.0); g.add(n);
        put(n, tube(0.62, 0.5, 5.0, planeMat, 12), 0, -0.2, 1.6, true);
        put(n, tube(0.68, 0.62, 0.7, planeDark, 12, true), 0, -0.2, 4.35, true);       // cowl lip
        put(n, tube(0.5, 0.66, 1.9, planeMat, 12), 0, -0.22, -1.7, true);              // fairing into the wing
        put(n, box(0.44, 0.3, 1.1, planeDark), 0, -0.68, 3.2, false);                  // oil cooler scoop
        const spin = put(n, new THREE.Mesh(new THREE.ConeGeometry(0.3, 1.0, 10), planeMetal), 0, -0.2, 5.1, true);
        spin.rotation.x = Math.PI / 2;
        put(n, box(0.28, 0.3, 1.0, planeDark), 0.26, 0.6, -0.4, false);                // exhaust stack
        put(n, box(0.5, 0.05, 1.4, planeDark), 0.3, 0.47, -0.9, false);                // soot streak
        const prop = new THREE.Group(); prop.position.set(0, -0.2, 5.5); n.add(prop);
        put(prop, new THREE.Mesh(new THREE.SphereGeometry(0.26, 10, 8), planeMetal), 0, 0, -0.12, false);
        for (let k = 0; k < 4; k++) {
          const arm = new THREE.Group(); arm.rotation.z = k * Math.PI / 2; prop.add(arm);
          const blade = put(arm, box(0.24, 1.75, 0.08, planeDark), 0, 1.15, 0, false);
          blade.rotation.y = 0.34;                                                     // blade pitch
          put(arm, box(0.22, 0.26, 0.07, planeStencil), 0, 2.08, 0, false);            // painted tip
        }
        put(prop, new THREE.Mesh(new THREE.RingGeometry(0.4, 2.05, 20), discMat), 0, 0, 0.12, false);
        props.push(prop);
      }

      // --- Gear sponsons, doors and belly hatches (wheels stay up in flight) ---------
      for (const s of [-1, 1]) {
        add(box(0.8, 1.5, 6.0, planeMat), s * 1.32, -0.35, -0.6);
        deco(box(0.62, 1.1, 1.2, planeMat), s * 1.28, -0.35, 3.1);
        deco(box(0.62, 1.1, 1.0, planeMat), s * 1.28, -0.35, -3.9);
        deco(box(0.07, 0.9, 2.1, planeTrim), s * 1.73, -0.5, 1.0);                     // gear doors
        deco(box(0.07, 0.9, 2.1, planeTrim), s * 1.73, -0.5, -2.2);
        deco(box(0.5, 0.13, 4.6, planeTrim), s * 1.4, -1.06, -0.6);                    // door seam
        deco(patch(1.43, 1.43, 0.45, s * Math.PI / 2, 0.22, planeStencil), 0, 0, 1.9); // side stencil block
      }
      deco(patch(1.3, 1.38, 1.9, 0, 0.5, planeTrim), 0, 0, 8.0);                       // nose gear doors

      // --- Tail: a tapering fin over the boom, stabiliser at its root ----------------
      // Every section shares a trailing edge at z -13.9, so the swept leading edge carries
      // the taper and the rudder can run the full height.
      add(box(0.36, 1.2, 3.6, planeMat), 0, 1.25, -9.6);                 // dorsal fillet
      add(box(0.38, 1.7, 3.6, planeMat), 0, 2.4, -12.1);
      add(box(0.34, 1.6, 3.0, planeMat), 0, 3.95, -12.4);
      add(box(0.3, 1.5, 2.3, planeMat), 0, 5.4, -12.75);
      const finLe = add(box(0.36, 4.9, 0.8, planeMat), 0, 3.85, -10.75);
      finLe.rotation.x = -0.28;
      deco(box(0.42, 0.28, 1.9, planeTrim), 0, 6.2, -12.95);             // fin cap
      deco(box(0.24, 4.7, 0.8, planeTrim), 0, 3.9, -14.15);              // rudder
      add(box(10.0, 0.32, 2.6, planeMat), 0, 1.75, -12.4);
      const stabLe = add(new THREE.Mesh(new THREE.CylinderGeometry(0.17, 0.17, 10.0, 8), planeMat), 0, 1.75, -11.2);
      stabLe.rotation.z = Math.PI / 2;
      for (const s of [-1, 1]) {
        deco(box(4.4, 0.24, 0.9, planeTrim), s * 2.6, 1.73, -14.1);      // elevators
        deco(box(1.0, 0.26, 1.9, planeMat), s * 5.3, 1.75, -12.75);      // stabiliser tips
        for (let k = 0; k < 4; k++) deco(box(0.05, 0.5, 0.3, planeStencil), s * 0.2, 2.5, -11.5 - k * 0.45);  // serial
      }
      deco(new THREE.Mesh(new THREE.SphereGeometry(0.14, 8, 6), strobeMat), 0, 6.45, -12.6);
      deco(new THREE.Mesh(new THREE.SphereGeometry(0.11, 8, 6), strobeMat), 0, 3.9, -14.6);

      // --- Aerials and beacons ------------------------------------------------------
      deco(box(0.06, 0.55, 0.5, planeDark), 0, 1.62, -3.4);
      deco(box(0.06, 0.42, 0.4, planeDark), 0, -1.5, 4.2);
      const hf = deco(box(0.04, 0.04, 6.8, planeDark), 0, 3.05, -6.6);
      hf.rotation.x = 0.345;                                             // HF wire, spine to fin
      deco(new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 6), beaconMat), 0, 1.5, -1.6);
      deco(new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 6), beaconMat), 0, -1.38, -1.6);

      g.userData.props = props;
      let ph = Math.random() * 4;
      // One call per frame handles the props, the beacons and the bay lights together.
      g.userData.tick = (dt, spin) => {
        for (const p of props) p.rotation.z += dt * spin;
        ph += dt;
        beaconMat.emissiveIntensity = ph % 1.15 < 0.14 ? 2.8 : 0.12;     // rotating red beacons
        strobeMat.emissiveIntensity = ph % 1.7 < 0.07 ? 6.0 : 0.08;      // wingtip and fin strobes
        jumpMat.emissiveIntensity = 1.0 + Math.sin(ph * 5.5) * 0.25;
      };
      return g;
    }
    function makeSupplyCrate() {
      const g = new THREE.Group();
      const crate = new THREE.Mesh(new THREE.BoxGeometry(1.0, 1.0, 1.0), crateMat); crate.castShadow = true; g.add(crate);
      for (const y of [-0.3, 0.3]) g.add(new THREE.Mesh(new THREE.BoxGeometry(1.04, 0.12, 1.04), crateBandMat)).position.y = y;
      const cross = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.08, 0.02), crateStencilMat); cross.position.set(0, 0.05, 0.51); g.add(cross);
      const cross2 = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.3, 0.02), crateStencilMat); cross2.position.set(0, 0.05, 0.51); g.add(cross2);
      const lid = new THREE.Group(); lid.position.set(0, 0.5, -0.5); g.add(lid);
      const lidBox = new THREE.Mesh(new THREE.BoxGeometry(1.06, 0.1, 1.06), crateBandMat); lidBox.position.set(0, 0.05, 0.5); lid.add(lidBox);
      g.userData.lid = lid;
      const chute = airborne.chute(); chute.position.y = 0.5;
      chute.scale.setScalar(0.05); chute.visible = false;
      g.add(chute);
      g.userData.chute = chute;
      // A compact protected white strobe, matching the HQ roof fixtures.
      const stem = new THREE.Mesh(new THREE.CylinderGeometry(.045,.045,.22,8),crateBandMat);
      stem.position.set(.34,.13,.76);lid.add(stem);
      const strobeMat = new THREE.MeshStandardMaterial({color:0xbfe6ff,emissive:0xdff3ff,emissiveIntensity:.05,roughness:.35});
      strobeMat.userData.airborneOwned = true;
      const strobe = new THREE.Mesh(new THREE.CylinderGeometry(.09,.09,.14,10),strobeMat);
      strobe.position.set(.34,.30,.76);lid.add(strobe);
      const cap = new THREE.Mesh(new THREE.CylinderGeometry(.11,.11,.025,10),crateBandMat);
      cap.position.set(.34,.383,.76);lid.add(cap);
      g.userData.strobe = strobe;
      airborne.prepare(g);
      return g;
    }
    function supplyLandingClear(x, z) {
      return Math.hypot(x, z) < landRadius - 8 && waterDepthAt(x, z) < 0.05 && terrainSlope(x, z) < 0.4 && !nearPOI(x, z, 6) && houseBoxDist(x, z) > 3;
    }
    function spawnSupplyDrop({ x: targetX, z: targetZ, contents = null, source = 'random' } = {}) {
      // With a target, use its landable centre or a nearby point at most 2.5 m away.
      const targeted = Number.isFinite(targetX) && Number.isFinite(targetZ);
      let x = 0, z = 0, ok = false;
      for (let tries = 0; tries < 40 && !ok; tries++) {
        const a = targeted ? tries * 2.39996323 : Math.random() * Math.PI * 2;
        const r = targeted ? (tries === 0 ? 0 : 2.5 * Math.sqrt(tries / 39)) : 22 + Math.random() * 34;
        x = (targeted ? targetX : nearestPlayer(0, 0).position.x) + Math.cos(a) * r;
        z = (targeted ? targetZ : nearestPlayer(0, 0).position.z) + Math.sin(a) * r;
        ok = supplyLandingClear(x, z);
      }
      if (!ok) return null;
      // The plane's run: in over the far side of the map, straight across the drop point.
      const hd = Math.random() * Math.PI * 2, dir = new THREE.Vector3(Math.sin(hd), 0, Math.cos(hd));
      const alt = sampleHeight(x, z) + 58, speed = 42;
      const start = new THREE.Vector3(x - dir.x * 170, alt, z - dir.z * 170);
      const plane = makeCargoPlane();
      plane.position.copy(start); plane.rotation.y = hd;
      scene.add(plane);
      const drop = { plane, dir, speed, x, z, contents, source, targeted,
        breather: source === 'breather' || !!nightPace?.inLull, dropped: false, t: 0, life: 340 / speed };
      supplyPlanes.push(drop);
      AudioSys.planeFlyover(340 / speed);
      AudioSys.musicCue('airdrop');
      publishUI('supply-drop', { phase: 'inbound', x, z, source, breather: drop.breather,
        bearing: compassName(x - nearestPlayer(0, 0).position.x, z - nearestPlayer(0, 0).position.z) });
      return drop;
    }
    function releaseSupplyCrate(p) {
      const g = makeSupplyCrate();
